import type { LiturgyBlock } from '../types';

export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-str-0001", "section": "service", "who": "reader", "text": "ВО СВЯТУЮ И ВЕЛИКУЮ СУББОТУ НА УТРЕНИ"},
  {"id": "ru-str-0002", "section": "service", "who": "rubric", "text": "Начало обычное, шестопсалмие и великая ектения."},
  {"id": "ru-str-0003", "section": "service", "who": "reader", "text": "На Бог Господь: тропари, глас 2"},
  {"id": "ru-str-0004", "section": "service", "who": "reader", "text": "Благородный Иосиф, / с древа сняв пречистое тело Твое, / чистым полотном обвив / и помазав благовониями, / в гробнице новой положил."},
  {"id": "ru-str-0005", "section": "service", "who": "reader", "text": "Слава: Когда сошел Ты к смерти, Жизнь бессмертная, / тогда ад умертвил Ты сиянием Божества. / Когда же Ты и умерших из преисподней воскресил, / все Силы Небесные взывали: / «Податель жизни, Христе Боже наш, слава Тебе!»"},
  {"id": "ru-str-0006", "section": "service", "who": "reader", "text": "И ныне: Женам-мироносицам / представ у гробницы, Ангел восклицал: / «Миро приличествует мертвым, / Христос же явился тлению неподвластным»."},
  {"id": "ru-str-0007", "section": "service", "who": "rubric", "text": "И начинаем петь Непорочны и похвалы, глас 5, совершая каждение в начале каждой статии."},
  {"id": "ru-str-0008", "section": "service", "who": "reader", "text": "Статия первая"},
  {"id": "ru-str-0009", "section": "service", "who": "reader", "text": "Благословен Ты, Господи, / научи меня повелениям Твоим."},
  {"id": "ru-str-0010", "section": "service", "who": "reader", "text": "Блаженны непорочные в пути, / ходящие в законе Господнем."},
  {"id": "ru-str-0011", "section": "service", "who": "reader", "text": "Ты – Жизнь, Христе, во гробе был положен / и Ангельские воинства поражались, / прославляя снисхождение Твое."},
  {"id": "ru-str-0012", "section": "service", "who": "reader", "text": "Блаженны исследующие свидетельства Его, / всем сердцем они взыщут Его."},
  {"id": "ru-str-0013", "section": "service", "who": "reader", "text": "Жизнь, как Ты умираешь? / И как во гробе обитаешь, / но царство смерти разрушаешь / и из ада мертвых воскрешаешь?"},
  {"id": "ru-str-0014", "section": "service", "who": "reader", "text": "Ибо не делающие беззакония / пошли по путям Его."},
  {"id": "ru-str-0015", "section": "service", "who": "reader", "text": "Величаем Тебя, Иисусе-Царь, / и почитаем погребение и страдания Твои, / которыми Ты спас нас от тления."},
  {"id": "ru-str-0016", "section": "service", "who": "reader", "text": "Ты заповедал заповеди Твои / сохранить твердо."},
  {"id": "ru-str-0017", "section": "service", "who": "reader", "text": "Определивший размеры земли, / Ты сегодня вмещаешься в тесном гробе, / Иисус, Царь над всем, / из гробниц умерших воскрешая."},
  {"id": "ru-str-0018", "section": "service", "who": "reader", "text": "О, если бы направлялись пути мои / к сохранению повелений Твоих."},
  {"id": "ru-str-0019", "section": "service", "who": "reader", "text": "Иисусе Христе мой, Царь всего, / что ища сошел Ты к находящимся во аде? / Не затем ли, чтобы освободить человеческий род?"},
  {"id": "ru-str-0020", "section": "service", "who": "reader", "text": "Тогда я не постыдился бы, / взирая на все заповеди Твои."},
  {"id": "ru-str-0021", "section": "service", "who": "reader", "text": "Владыка всех видится мертвым / и в новом гробе полагается / Опустошивший гробницы мертвых."},
  {"id": "ru-str-0022", "section": "service", "who": "reader", "text": "Я прославлю Тебя в правоте сердца, / когда научусь судам правды Твоей."},
  {"id": "ru-str-0023", "section": "service", "who": "reader", "text": "Ты – Жизнь, Христе, во гробе был положен, / и смерть погубил смертью Своею / и источил миру жизнь."},
  {"id": "ru-str-0024", "section": "service", "who": "reader", "text": "Повеления Твои сохраню; / не оставь меня до конца."},
  {"id": "ru-str-0025", "section": "service", "who": "reader", "text": "Как злодей Ты к злодеям был причислен, Христе, / оправдывая всех нас / от злодеяния древнего запинателя."},
  {"id": "ru-str-0026", "section": "service", "who": "reader", "text": "В чем исправит юноша путь свой? / В сохранении слов Твоих."},
  {"id": "ru-str-0027", "section": "service", "who": "reader", "text": "Совершенный красотою среди всех людей, / как мертвец, не имеющий вида являешься, / Ты, украсивший природу всего."},
  {"id": "ru-str-0028", "section": "service", "who": "reader", "text": "Всем сердцем моим я взыскал Тебя, / не отринь меня от заповедей Твоих."},
  {"id": "ru-str-0029", "section": "service", "who": "reader", "text": "Как вынесет ад Твое пришествие, Спаситель, / и не скорее ли он сокрушится, омрачаемый, / ослепленный сиянием блеска Твоего света?"},
  {"id": "ru-str-0030", "section": "service", "who": "reader", "text": "В сердце моём я скрыл изречения Твои, / чтобы не согрешить пред Тобою."},
  {"id": "ru-str-0031", "section": "service", "who": "reader", "text": "Иисус, сладкий мой и спасительный свет, / как Ты во мрачном гробе скрылся? / О, невыразимое и несказанное терпение!"},
  {"id": "ru-str-0032", "section": "service", "who": "reader", "text": "Благословен Ты, Господи; / научи меня повелениям Твоим."},
  {"id": "ru-str-0033", "section": "service", "who": "reader", "text": "Недоумевает невещественное естество, Христе, / и множество бесплотных о таинстве / неизъяснимого и несказанного Твоего погребения."},
  {"id": "ru-str-0034", "section": "service", "who": "reader", "text": "Устами моими я возвестил / все суды уст Твоих."},
  {"id": "ru-str-0035", "section": "service", "who": "reader", "text": "О, необычайные чудеса! О, дела небывалые! / Дарующий мне дыхание бездыханным относится, / погребаемый руками Иосифа."},
  {"id": "ru-str-0036", "section": "service", "who": "reader", "text": "На пути свидетельств Твоих я насладился, как во всяком богатстве."},
  {"id": "ru-str-0037", "section": "service", "who": "reader", "text": "Хотя и во гроб зашел, Ты Христе, / но никак не отлучился от Отеческих недр, / – это вместе необычайно и дивно."},
  {"id": "ru-str-0038", "section": "service", "who": "reader", "text": "О заповедях Твоих буду рассуждать, / и уразумею пути Твои."},
  {"id": "ru-str-0039", "section": "service", "who": "reader", "text": "Истинный Царь и неба и земли, / хотя и в теснейшем гробе Ты был затворен, / но все творение узнало Тебя, Иисусе."},
  {"id": "ru-str-0040", "section": "service", "who": "reader", "text": "В повеления Твои буду вникать, / не забуду слов Твоих."},
  {"id": "ru-str-0041", "section": "service", "who": "reader", "text": "Когда был Ты положен во гробе, Создатель-Христос, / поколебались основания ада / и открылись гробницы смертных."},
  {"id": "ru-str-0042", "section": "service", "who": "reader", "text": "Воздай рабу Твоему, оживи меня, / и сохраню я слова Твои."},
  {"id": "ru-str-0043", "section": "service", "who": "reader", "text": "Держащий землю в руке, умерщвленный по плоти / под землею ныне удерживается, / от тесноты ада избавляя мертвых."},
  {"id": "ru-str-0044", "section": "service", "who": "reader", "text": "Открой очи мои, / и уразумею чудеса из закона Твоего."},
  {"id": "ru-str-0045", "section": "service", "who": "reader", "text": "Из тления взошел Ты, жизнь моя, Спаситель, / когда умер и к мертвым пришел, / и сокрушил засовы ада."},
  {"id": "ru-str-0046", "section": "service", "who": "reader", "text": "Поселенец я на земле: не скрой от меня заповедей Твоих."},
  {"id": "ru-str-0047", "section": "service", "who": "reader", "text": "Как светильник светлый / ныне плоть Бога под землей, как под сосудом скрывается, / и гонит пребывавшую во аде тьму."},
  {"id": "ru-str-0048", "section": "service", "who": "reader", "text": "Возжаждала душа моя, / желая судов Твоих во всякое время."},
  {"id": "ru-str-0049", "section": "service", "who": "reader", "text": "Стекается невещественных воинств множество, / чтобы с Иосифом и Никодимом / похоронить Тебя, Невместимого, в тесном гробе."},
  {"id": "ru-str-0050", "section": "service", "who": "reader", "text": "Ты укротил гордых; / прокляты уклоняющиеся от заповедей Твоих."},
  {"id": "ru-str-0051", "section": "service", "who": "reader", "text": "Добровольно умерщвленный и положенный под землею, / Ты, Иисусе мой, Источник жизни, / оживил меня, умерщвленного преступлением горьким."},
  {"id": "ru-str-0052", "section": "service", "who": "reader", "text": "Сними с меня поношение и презрение, / ибо свидетельств Твоих я взыскал."},
  {"id": "ru-str-0053", "section": "service", "who": "reader", "text": "Изменялось все творение от Твоих страданий, / ибо всё Тебе, Слово, сострадало, / зная Тебя, Удерживающего все."},
  {"id": "ru-str-0054", "section": "service", "who": "reader", "text": "Ибо вот, сели князья и на меня клеветали, / раб же Твой рассуждал о повелениях Твоих."},
  {"id": "ru-str-0055", "section": "service", "who": "reader", "text": "Приняв во чрево Камень Жизни, / всепожирающий ад извергнул мертвых, / которых поглотил от века."},
  {"id": "ru-str-0056", "section": "service", "who": "reader", "text": "Ибо и свидетельства Твои – занятие моё, / и советники мои – повеления Твои."},
  {"id": "ru-str-0057", "section": "service", "who": "reader", "text": "В гробнице новой Ты положен, Христе, / и обновил природу смертных, / воскреснув, как подобает Богу, из мертвых."},
  {"id": "ru-str-0058", "section": "service", "who": "reader", "text": "Приникла к земле душа моя; / оживи меня по слову Твоему."},
  {"id": "ru-str-0059", "section": "service", "who": "reader", "text": "На землю Ты сошел, чтобы спасти Адама, / и на земле не найдя его, Владыка, / до самого ада сошел, его ища."},
  {"id": "ru-str-0060", "section": "service", "who": "reader", "text": "Пути мои я возвестил, и Ты услышал меня; / научи меня повелениям Твоим."},
  {"id": "ru-str-0061", "section": "service", "who": "reader", "text": "Приходит в смятение от страха вся земля, Слово, / и звезда утренняя лучи сокрыла, / когда Ты, Величайший Свет, землею был сокрыт."},
  {"id": "ru-str-0062", "section": "service", "who": "reader", "text": "Дай мне понять путь повелений Твоих, / и буду рассуждать о чудесах Твоих."},
  {"id": "ru-str-0063", "section": "service", "who": "reader", "text": "Как смертный, Ты Спаситель, добровольно умираешь, / но как Бог воскресил умерших / из гробниц и глубины грехов."},
  {"id": "ru-str-0064", "section": "service", "who": "reader", "text": "Задремала душа моя от нерадения: / укрепи меня в словах Твоих."},
  {"id": "ru-str-0065", "section": "service", "who": "reader", "text": "Слезные сетования над Тобою, Иисусе, / матерински проливая, взывала Чистая: / «Как погребу Тебя, Сын?»"},
  {"id": "ru-str-0066", "section": "service", "who": "reader", "text": "Путь неправды удали от меня, / и законом Твоим помилуй меня."},
  {"id": "ru-str-0067", "section": "service", "who": "reader", "text": "Как пшеничное зерно, погрузившееся в недра земли, / Ты принес плодородный колос, / воскресив смертных, происшедших от Адама."},
  {"id": "ru-str-0068", "section": "service", "who": "reader", "text": "Путь истины я избрал, / и судов Твоих не забыл."},
  {"id": "ru-str-0069", "section": "service", "who": "reader", "text": "Под землю Ты ныне был скрыт, как солнце, / и ночью смерти был объят, / но воссияй еще светлее, Спаситель!"},
  {"id": "ru-str-0070", "section": "service", "who": "reader", "text": "Я прилепился к свидетельствам Твоим; / Господи, не постыди меня."},
  {"id": "ru-str-0071", "section": "service", "who": "reader", "text": "Как солнечный круг луна закрывает, / так и Тебя, Спаситель, гроб ныне сокрыл, / затмившегося смертью по плоти."},
  {"id": "ru-str-0072", "section": "service", "who": "reader", "text": "Путь заповедей Твоих я пробежал, / когда Ты расширил сердце моё."},
  {"id": "ru-str-0073", "section": "service", "who": "reader", "text": "Жизнь, вкусившая смерти, Христос, / от смерти людей освободил, / и всем ныне дарует жизнь."},
  {"id": "ru-str-0074", "section": "service", "who": "reader", "text": "Положи мне, Господи, законом путь повелений Твоих, / и буду искать его постоянно."},
  {"id": "ru-str-0075", "section": "service", "who": "reader", "text": "В древности умерщвленного из зависти Адама / Ты возводишь к жизни умерщвлением Твоим, / явившись, Спаситель, во плоти как новый Адам."},
  {"id": "ru-str-0076", "section": "service", "who": "reader", "text": "Вразуми меня, и исследую закон Твой, / и сохраню его всем сердцем моим."},
  {"id": "ru-str-0077", "section": "service", "who": "reader", "text": "Видя Тебя, Спаситель, распростертым, мертвым ради нас, / невещественные полки поражались, / закрываясь крылами."},
  {"id": "ru-str-0078", "section": "service", "who": "reader", "text": "Направь меня на стезю заповедей Твоих, / ибо я её возжелал."},
  {"id": "ru-str-0079", "section": "service", "who": "reader", "text": "Сняв Тебя, Слово, мертвым с Древа, / Иосиф ныне положил во гроб, / но восстань, спасая всех, как Бог."},
  {"id": "ru-str-0080", "section": "service", "who": "reader", "text": "Склони сердце моё к свидетельствам Твоим, / а не к любостяжанию."},
  {"id": "ru-str-0081", "section": "service", "who": "reader", "text": "Спаситель, ставший радостью для Ангелов, / ныне сделался и причиной их печали, / видимый по плоти бездыханным мертвецом."},
  {"id": "ru-str-0082", "section": "service", "who": "reader", "text": "Отврати очи мои, чтобы не видеть суеты; / на пути Твоем оживи меня."},
  {"id": "ru-str-0083", "section": "service", "who": "reader", "text": "Вознесенный на Древо, Ты и живущих людей с Собой возносишь, / а оказавшись под землею, / под нею лежащих воскрешаешь."},
  {"id": "ru-str-0084", "section": "service", "who": "reader", "text": "Поставь рабу Твоему / слово Твоё в страх Твой."},
  {"id": "ru-str-0085", "section": "service", "who": "reader", "text": "Как лев уснув по плоти, Спаситель, / Ты как некий львенок, мертвый воскресаешь, / сбросив плотскую старость."},
  {"id": "ru-str-0086", "section": "service", "who": "reader", "text": "Удали поношение моё, которого я боюсь, / ибо суды Твои благи."},
  {"id": "ru-str-0087", "section": "service", "who": "reader", "text": "Ты, взявший ребро Адама, из которого Еву создал, / был в ребра пронзен / и источил очищающие потоки."},
  {"id": "ru-str-0088", "section": "service", "who": "reader", "text": "Вот, я возжелал заповедей Твоих, / в правде Твоей оживи меня."},
  {"id": "ru-str-0089", "section": "service", "who": "reader", "text": "В древности агнец тайно приносится в жертву, / Ты же, беззлобный, принесенный в жертву открыто, / все творение очистил, Спаситель."},
  {"id": "ru-str-0090", "section": "service", "who": "reader", "text": "И да придет на меня милость Твоя, Господи, / спасение Твоё, по слову Твоему."},
  {"id": "ru-str-0091", "section": "service", "who": "reader", "text": "Кто изъяснит явление страшное, поистине небывалое, / ибо Владычествующий над творением в сей день / принимает страдание и умирает ради нас."},
  {"id": "ru-str-0092", "section": "service", "who": "reader", "text": "И я отвечу поносящим меня слово, / ибо уповаю на слова Твои."},
  {"id": "ru-str-0093", "section": "service", "who": "reader", "text": "«Как Жизни Податель созерцается мертвым?» / – поражаясь, восклицали Ангелы, – / «И как во гробе заключается Бог?»"},
  {"id": "ru-str-0094", "section": "service", "who": "reader", "text": "И не отними от уст моих слова истины до конца, / ибо на суды Твои я уповал."},
  {"id": "ru-str-0095", "section": "service", "who": "reader", "text": "Из ребра Твоего, Спаситель, копьем пронзенного, / Ты, Жизнь, меня некогда из жизни изгнавшая, / жизнь проливаешь и оживляешь ею меня."},
  {"id": "ru-str-0096", "section": "service", "who": "reader", "text": "И буду хранить закон Твой всегда, / вовек и во век века."},
  {"id": "ru-str-0097", "section": "service", "who": "reader", "text": "Распростертый на Древе, Ты собрал к Себе смертных, / и пронзенный в ребра, изливаешь всем / источающее жизнь прощение, Иисусе."},
  {"id": "ru-str-0098", "section": "service", "who": "reader", "text": "И ходил я на просторе, / ибо заповедей Твоих взыскал."},
  {"id": "ru-str-0099", "section": "service", "who": "reader", "text": "Благородный Иосиф выражает страх, / и благолепно погребает Тебя, Спаситель, как мертвеца, / и ужасается Твоего повергающего в трепет облика."},
  {"id": "ru-str-0100", "section": "service", "who": "reader", "text": "И говорил о свидетельствах Твоих пред царями / и не стыдился."},
  {"id": "ru-str-0101", "section": "service", "who": "reader", "text": "Добровольно под землю сойдя, как смертный, / Ты возводишь от земли к небесному / оттуда падших, Иисусе."},
  {"id": "ru-str-0102", "section": "service", "who": "reader", "text": "И упражнялся в заповедях Твоих, / которые возлюбил крепко."},
  {"id": "ru-str-0103", "section": "service", "who": "reader", "text": "Хотя и был Ты видим мертвым, но живым пребывая как Бог, / Ты возводишь от земли к небесному / оттуда падших, Иисусе."},
  {"id": "ru-str-0104", "section": "service", "who": "reader", "text": "И поднял руки мои к заповедям Твоим, / которые возлюбил."},
  {"id": "ru-str-0105", "section": "service", "who": "reader", "text": "Хотя и был Ты видим мертвым, но живым пребывая как Бог, / умерщвленных смертных вновь оживил, / умертвив меня умертвившего."},
  {"id": "ru-str-0106", "section": "service", "who": "reader", "text": "И рассуждал / о повелениях Твоих."},
  {"id": "ru-str-0107", "section": "service", "who": "reader", "text": "О, эта радость! О, великое наслаждение! / Те, которыми исполнил Ты находившихся во аде, / излучив в глубинах мрачных свет!"},
  {"id": "ru-str-0108", "section": "service", "who": "reader", "text": "Вспомни слово Твоё к рабу Твоему, / которым Ты вселил надежду в меня."},
  {"id": "ru-str-0109", "section": "service", "who": "reader", "text": "Поклоняюсь страданию, воспеваю погребение, / величаю Твое могущество, Человеколюбец, / которыми мы освобождены от губительных страстей."},
  {"id": "ru-str-0110", "section": "service", "who": "reader", "text": "Это утешило меня в унижении моём, / что слово Твоё оживило меня."},
  {"id": "ru-str-0111", "section": "service", "who": "reader", "text": "Против Тебя, Христе, меч блистал, / и вот, – меч сильного притупляется, / и вспять обращается меч Эдемский."},
  {"id": "ru-str-0112", "section": "service", "who": "reader", "text": "Высокомерные до крайности преступали закон, / но я от закона Твоего не уклонился."},
  {"id": "ru-str-0113", "section": "service", "who": "reader", "text": "Агница, видя Агнца во время заклания, / поражаемая стрелами, восклицала, / побуждая взывать и стадо."},
  {"id": "ru-str-0114", "section": "service", "who": "reader", "text": "Вспомнил суды Твои от века, Господи, / и утешился."},
  {"id": "ru-str-0115", "section": "service", "who": "reader", "text": "Хотя бы Ты и был в могиле погребен, / хотя бы и сошел во ад, Спаситель, / но и могилы Ты опустошил и ад обнажил, Христе."},
  {"id": "ru-str-0116", "section": "service", "who": "reader", "text": "Печаль объяла меня от грешников, / оставляющих закон Твой."},
  {"id": "ru-str-0117", "section": "service", "who": "reader", "text": "Добровольно сойдя под землю, Спаситель, / Ты умерщвленных смертных оживил / и возвел во славу Отца."},
  {"id": "ru-str-0118", "section": "service", "who": "reader", "text": "Как песни были мне повеления Твои / на месте странствия моего."},
  {"id": "ru-str-0119", "section": "service", "who": "reader", "text": "Один из Троицы во плоти / ради нас позорную смерть претерпел: / содрогается солнце и трясется земля."},
  {"id": "ru-str-0120", "section": "service", "who": "reader", "text": "Вспомнил я ночью имя Твоё, Господи, / и сохранил закон Твой."},
  {"id": "ru-str-0121", "section": "service", "who": "reader", "text": "Как происшедшие из источника горького, / отпрыски колена Иудина во рве положили / Питателя и Подателя манны Иисуса."},
  {"id": "ru-str-0122", "section": "service", "who": "reader", "text": "Это случилось со мной, / ибо повелений Твоих я взыскал."},
  {"id": "ru-str-0123", "section": "service", "who": "reader", "text": "Судия, как судимый пред судьею Пилатом / и предстал, и неправедно был осужден / на смерть чрез Древо Крестное."},
  {"id": "ru-str-0124", "section": "service", "who": "reader", "text": "Удел мой, Господи, сказал я, – / сохранить закон Твой."},
  {"id": "ru-str-0125", "section": "service", "who": "reader", "text": "Кичливый Израиль, запятнанный убийством народ, / что случилось с тобою, что Варавве дал ты свободу, / а Спасителя предал Кресту?"},
  {"id": "ru-str-0126", "section": "service", "who": "reader", "text": "Помолился я пред лицом Твоим всем сердцем моим; / помилуй меня по слову Твоему."},
  {"id": "ru-str-0127", "section": "service", "who": "reader", "text": "Создавший Адама Своею рукой из земли, / ради него по природе стал человеком / и был распят по воле Своей."},
  {"id": "ru-str-0128", "section": "service", "who": "reader", "text": "Обдумал я пути Твои / и обратил ноги мои ко свидетельствам Твоим."},
  {"id": "ru-str-0129", "section": "service", "who": "reader", "text": "Послушный, Слово, Отцу Своему, / Ты сошел вплоть до страшного ада / и воскресил человеческий род."},
  {"id": "ru-str-0130", "section": "service", "who": "reader", "text": "Я приготовился и не смутился, / чтобы сохранить заповеди Твои."},
  {"id": "ru-str-0131", "section": "service", "who": "reader", "text": "«Увы Мне, Свет мира! Увы Мне, Мой Свет, / Иисусе Мой вожделеннейший!» – / в скорбной песне горестно Дева взывала."},
  {"id": "ru-str-0132", "section": "service", "who": "reader", "text": "Верви грешников обвили меня, – / и закона Твоего я не забыл."},
  {"id": "ru-str-0133", "section": "service", "who": "reader", "text": "Завистливый, жаждущий убийства и преступный народ, / хотя бы пеленами и самым платом ты устыдился / по воскресении Христа."},
  {"id": "ru-str-0134", "section": "service", "who": "reader", "text": "В полночь я вставал прославлять Тебя за праведные суды Твои."},
  {"id": "ru-str-0135", "section": "service", "who": "reader", "text": "Приди же, мерзкий ученик-убийца, / и ход злодеяния твоего разъясни мне, / отчего ты стал предателем Христа."},
  {"id": "ru-str-0136", "section": "service", "who": "reader", "text": "Общник я всем боящимся Тебя / и хранящим заповеди Твои."},
  {"id": "ru-str-0137", "section": "service", "who": "reader", "text": "Как бы некий человеколюбец лицемеришь ты, глупец, / и слепец, всегубительнейший, непримиримый, / миро продавший за деньги."},
  {"id": "ru-str-0138", "section": "service", "who": "reader", "text": "Милости Твоей, Господи, полна земля: / повелениям Твоим научи меня."},
  {"id": "ru-str-0139", "section": "service", "who": "reader", "text": "За небесное Миро какую ты цену получил? / За бесценное что равноценное принял? / Бешенство снискал ты, проклятый сатана."},
  {"id": "ru-str-0140", "section": "service", "who": "reader", "text": "Благостно поступил Ты с рабом Твоим, / Господи, по слову Твоему."},
  {"id": "ru-str-0141", "section": "service", "who": "reader", "text": "Если ты нищелюбец и о мvре жалеешь, / изливаемом в умилостивление о душе, / то как продаешь за золото Светозарного?"},
  {"id": "ru-str-0142", "section": "service", "who": "reader", "text": "Доброте, и благонравию, и знанию научи меня, / ибо заповедям Твоим я поверил."},
  {"id": "ru-str-0143", "section": "service", "who": "reader", "text": "О, Боже и Слово! О, Радость Моя, / как перенесу трехдневное Твое погребение? / Ныне терзаюсь Я материнским сердцем!"},
  {"id": "ru-str-0144", "section": "service", "who": "reader", "text": "Прежде чем смирился, я погрешил, / потому слово Твое сохранил."},
  {"id": "ru-str-0145", "section": "service", "who": "reader", "text": "«Кто даст Мне воду и источники слез», – / восклицала Богоневестная Дева, – / чтобы оплакать Сладкого Моего Иисуса?»"},
  {"id": "ru-str-0146", "section": "service", "who": "reader", "text": "Благ Ты, Господи, и в благости Твоей / научи меня повелениям Твоим."},
  {"id": "ru-str-0147", "section": "service", "who": "reader", "text": "О, холмы, и долины, и множество людей! / Все восплачьте и сетуйте со Мною, / Матерью Бога вашего!"},
  {"id": "ru-str-0148", "section": "service", "who": "reader", "text": "Умножилась против меня неправда гордых, / я же буду всем сердцем моим исследовать заповеди Твои."},
  {"id": "ru-str-0149", "section": "service", "who": "reader", "text": "«Когда увижу Тебя, Спаситель, Вечный Свет, / радость и наслаждение сердца Моего?» – / горестно взывала Дева."},
  {"id": "ru-str-0150", "section": "service", "who": "reader", "text": "Сгустилось, как молоко, сердце их, / я же в Твой закон углубился."},
  {"id": "ru-str-0151", "section": "service", "who": "reader", "text": "Хотя и принял рассечение Ты, Спаситель, как обрывистая скала, / но источил живой поток, / будучи источником жизни."},
  {"id": "ru-str-0152", "section": "service", "who": "reader", "text": "Благо мне, что ты смирил меня, чтобы мне изучить повеления Твои."},
  {"id": "ru-str-0153", "section": "service", "who": "reader", "text": "Как орошаемые двойною рекой, / из одного родника – ребр Твоих истекающей, / мы получаем плод – бессмертную жизнь."},
  {"id": "ru-str-0154", "section": "service", "who": "reader", "text": "Благ для меня закон уст Твоих / больше тысяч золота и серебра."},
  {"id": "ru-str-0155", "section": "service", "who": "reader", "text": "Добровольно явился Ты, Слово, мертвым во гробе, / но Ты живешь, и смертных, как предсказал, / пробудишь, Спаситель мой, Своим воскресением."},
  {"id": "ru-str-0156", "section": "service", "who": "reader", "text": "Слава, Троичен: Воспеваем Тебя, Слово, Бога всех, / со Отцом и Святым Твоим Духом / и славим Твое Божественное погребение."},
  {"id": "ru-str-0157", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Превозносим Тебя, Богородица чистая, / и с верою чтим погребение трехдневное / Сына Твоего и Бога нашего."},
  {"id": "ru-str-0158", "section": "service", "who": "rubric", "text": "И оба хора поют вместе поют первый припев:"},
  {"id": "ru-str-0159", "section": "service", "who": "choir", "text": "Ты – Жизнь, Христе, во гробе был положен / и Ангельские воинства поражались, / прославляя снисхождение Твое."},
  {"id": "ru-str-0160", "section": "service", "who": "rubric", "text": "Затем ектения малая, молитва 3 и возглас:"},
  {"id": "ru-str-0161", "section": "service", "who": "choir", "text": "Ибо благословенно Твоё имя и прославлено Твоё Царство, Отца, и Сына, и Святого Духа ныне, и всегда, и во веки веков."},
  {"id": "ru-str-0162", "section": "service", "who": "rubric", "text": "И после каждения начинает вторую статию."},
  {"id": "ru-str-0163", "section": "service", "who": "choir", "text": "Статия вторая"},
  {"id": "ru-str-0164", "section": "service", "who": "choir", "text": "Достойно есть прославлять Тебя, жизни Подателя, / на Кресте руки простершего / и могущество врага сокрушившего."},
  {"id": "ru-str-0165", "section": "service", "who": "choir", "text": "Руки Твои сотворили меня и создали меня; / вразуми меня, и научусь заповедям Твоим."},
  {"id": "ru-str-0166", "section": "service", "who": "choir", "text": "Достойно есть прославлять Тебя, Творца всего, / ибо через Твои страдания мы обладаем бесстрастием, / избавленные от тления."},
  {"id": "ru-str-0167", "section": "service", "who": "choir", "text": "Боящиеся Тебя увидят меня и возвеселятся, / ибо на слова Твои я уповал."},
  {"id": "ru-str-0168", "section": "service", "who": "choir", "text": "Содрогнулась земля и солнце скрылось, Спаситель, / когда Ты, Христе, Немеркнущий Свет, / зашел во гробе по плоти."},
  {"id": "ru-str-0169", "section": "service", "who": "choir", "text": "Я познал, Господи, что правда – суды Твои, / и по истине Ты смирил меня."},
  {"id": "ru-str-0170", "section": "service", "who": "choir", "text": "Ты, Христе, уснул животворным сном во гробе / и от тяжкого сна греха / пробудил человеческий род."},
  {"id": "ru-str-0171", "section": "service", "who": "choir", "text": "Да будет же милость Твоя утешением мне, / по слову Твоему к рабу Твоему."},
  {"id": "ru-str-0172", "section": "service", "who": "choir", "text": "«Я единственная из женщин родила Тебя без мучений, Дитя, / ныне же при страдании Твоем / переношу нестерпимые муки», – говорила Пречистая."},
  {"id": "ru-str-0173", "section": "service", "who": "choir", "text": "Да придет ко мне сострадание Твоё, и буду жить, / ибо закон Твой – занятие моё."},
  {"id": "ru-str-0174", "section": "service", "who": "choir", "text": "Созерцая Тебя, Спаситель, в высоте неразлучно с Отцом пребывающим, / а внизу мертвецом, на земле распростертым, / ужасаются Серафимы."},
  {"id": "ru-str-0175", "section": "service", "who": "choir", "text": "Да постыдятся гордые, ибо неправедно сотворили беззаконие против меня, / я же буду рассуждать о заповедях Твоих."},
  {"id": "ru-str-0176", "section": "service", "who": "choir", "text": "Раздирается завеса храма при распятии Твоем, Слово, / светила же скрывают свой свет, / когда Ты, Солнце, был сокрыт под землею."},
  {"id": "ru-str-0177", "section": "service", "who": "choir", "text": "Да обратятся ко мне боящиеся Тебя / и знающие свидетельства Твои."},
  {"id": "ru-str-0178", "section": "service", "who": "choir", "text": "Одним мановением в начале круг земной утвердивший, / как человек зашел бездыханным под землю. / Содрогнись же от этого зрелища, небо!"},
  {"id": "ru-str-0179", "section": "service", "who": "choir", "text": "Да будет сердце моё непорочно в повелениях Твоих, / чтобы мне не постыдиться."},
  {"id": "ru-str-0180", "section": "service", "who": "choir", "text": "Ты зашел под землю, человека Своею рукою Создавший, / чтобы восстановить от падения множества смертных / всесильною мощью."},
  {"id": "ru-str-0181", "section": "service", "who": "choir", "text": "Изнемогает о спасении Твоем душа моя, / и на слова Твои я уповал."},
  {"id": "ru-str-0182", "section": "service", "who": "choir", "text": "Придите, плач священный воспоем Христу умершему, / как в древности жены-мироносицы, / чтобы и «Радуйтесь!» нам услышать с ними."},
  {"id": "ru-str-0183", "section": "service", "who": "choir", "text": "Изнемогли очи мои о слове Твоем; я говорю: / «Когда Ты утешишь меня?»"},
  {"id": "ru-str-0184", "section": "service", "who": "choir", "text": "Ты, Слово, – поистине неиссякаемое миро, / потому и приносили Тебе миро жены мироносицы, / – живому, как мертвецу."},
  {"id": "ru-str-0185", "section": "service", "who": "choir", "text": "Ибо стал я, как мех на морозе, повелений Твоих не забыл."},
  {"id": "ru-str-0186", "section": "service", "who": "choir", "text": "Погребенный, царство ада Ты, Христе, сокрушаешь; / смертью же смерть умерщвляешь / и избавляешь от тления рожденных на земле."},
  {"id": "ru-str-0187", "section": "service", "who": "choir", "text": "Сколько дней раба Твоего? / Когда сотворишь мне суд против гонящих меня?"},
  {"id": "ru-str-0188", "section": "service", "who": "choir", "text": "Потоки жизни изливающая Божия Премудрость, / сойдя во гроб, оживотворяет / пребывающих в недоступных глубинах ада."},
  {"id": "ru-str-0189", "section": "service", "who": "choir", "text": "Поведали мне законопреступники рассуждения, / но не как закон Твой, Господи."},
  {"id": "ru-str-0190", "section": "service", "who": "choir", "text": "Чтобы обновить сокрушенную природу смертных, / Я по воле Своей уязвлен смертью по плоти. / Матерь Моя, не терзайся рыданиями."},
  {"id": "ru-str-0191", "section": "service", "who": "choir", "text": "Все заповеди Твои – истина; / стали гнать меня неправедно, помоги мне."},
  {"id": "ru-str-0192", "section": "service", "who": "choir", "text": "Зашел Ты под землю, Утренняя Звезда правды, / и мертвых, как от сна пробудил, / изгнав всю бывшую во аде тьму."},
  {"id": "ru-str-0193", "section": "service", "who": "choir", "text": "Едва не погубили меня на земле, / но я не оставил заповедей Твоих."},
  {"id": "ru-str-0194", "section": "service", "who": "choir", "text": "Зерно двухприродное, животворное / в недра земли сеется со слезами в сей день, / но, произросши, оно наполнит радостью мир."},
  {"id": "ru-str-0195", "section": "service", "who": "choir", "text": "По милости Твоей оживи меня, / и сохраню свидетельства уст Твоих."},
  {"id": "ru-str-0196", "section": "service", "who": "choir", "text": "Скрылся Адам от Бога, ходящего в раю, / но радуется во ад Пришедшему / некогда падший, но ныне воздвигнутый."},
  {"id": "ru-str-0197", "section": "service", "who": "choir", "text": "Вовек, Господи, слово Твоё / пребывает на небесах."},
  {"id": "ru-str-0198", "section": "service", "who": "choir", "text": "Совершает возлияния слез Родившая Тебя, / Тебе, Христе, лежащему плотию во гробе, / взывая: «Воскресни, Дитя, как Ты предсказал!»"},
  {"id": "ru-str-0199", "section": "service", "who": "choir", "text": "В род и род истина Твоя: / Ты основал землю, и она пребывает."},
  {"id": "ru-str-0200", "section": "service", "who": "choir", "text": "Благоговейно скрывая Тебя в новом гробе, Иосиф / песнопения отходные, достойные Бога, / смешав их с рыданиями воспевает Тебе, Спаситель."},
  {"id": "ru-str-0201", "section": "service", "who": "choir", "text": "По велению Твоему пребывает день, / ибо все служит Тебе."},
  {"id": "ru-str-0202", "section": "service", "who": "choir", "text": "Видя Тебя, пригвожденным гвоздями к Кресту, / Матерь Твоя, Слово Божие, / гвоздями горькой скорби и стрелами душу Свою пронзает."},
  {"id": "ru-str-0203", "section": "service", "who": "choir", "text": "Ибо если бы не был закон Твой занятием моим, / тогда погиб бы я в унижении моём."},
  {"id": "ru-str-0204", "section": "service", "who": "choir", "text": "Видя Тебя, Услада всех, Матерь Твоя, / питием напояемого горьким, / наводняет взоры слезами горестно."},
  {"id": "ru-str-0205", "section": "service", "who": "choir", "text": "Вовек не забуду повелений Твоих, / ибо ими Ты меня оживил."},
  {"id": "ru-str-0206", "section": "service", "who": "choir", "text": "«Уязвляюсь тяжко и терзаюсь внутренне, Слово, / видя заклание Твое неправедное», – / взывала Пречистая с плачем."},
  {"id": "ru-str-0207", "section": "service", "who": "choir", "text": "Твой я, спаси меня, / ибо повелений Твоих я взыскал."},
  {"id": "ru-str-0208", "section": "service", "who": "choir", "text": "«Взор Твой сладкий и уста как закрою, Слово? / Как же по образу умерших Тебя погребу?» – / с трепетом взывал Иосиф."},
  {"id": "ru-str-0209", "section": "service", "who": "choir", "text": "Стали ждать меня грешники, чтобы меня погубить, – / я же понял свидетельства Твои."},
  {"id": "ru-str-0210", "section": "service", "who": "choir", "text": "Песнопения надгробные Иосиф и Никодим / воспевают ныне Христу умершему, / и вместе с ними поют Серафимы."},
  {"id": "ru-str-0211", "section": "service", "who": "choir", "text": "Всякого свершения предел я узрел, – / широка заповедь Твоя весьма."},
  {"id": "ru-str-0212", "section": "service", "who": "choir", "text": "Ты заходишь под землю, Спаситель, Солнце правды, / оттого родившая Тебя Луна затмевается от скорбей, / Твоего лицезрения лишаясь."},
  {"id": "ru-str-0213", "section": "service", "who": "choir", "text": "Как возлюбил я закон Твой, Господи, / целый день он – занятие моё."},
  {"id": "ru-str-0214", "section": "service", "who": "choir", "text": "Содрогнулся ад, видя Тебя, Спаситель, Жизни Подателя, / расхищающего его богатство / и от века умерших воскрешающего."},
  {"id": "ru-str-0215", "section": "service", "who": "choir", "text": "Более врагов моих Ты умудрил меня заповедью Твоею, / ибо она – моя вовек."},
  {"id": "ru-str-0216", "section": "service", "who": "choir", "text": "Солнце излучает сияние после ночи, / но и Ты, Слово воскресши, радостно воссияешь / после смерти, как из брачного чертога."},
  {"id": "ru-str-0217", "section": "service", "who": "choir", "text": "Лучше всех учащих меня я стал понимать, / ибо свидетельства Твои – занятие моё."},
  {"id": "ru-str-0218", "section": "service", "who": "choir", "text": "Земля, приняв Тебя, Создатель, в недра, / охваченная страхом, сотрясается, / пробудив своим сотрясением мертвых."},
  {"id": "ru-str-0219", "section": "service", "who": "choir", "text": "Лучше старцев я стал понимать, / ибо заповедей Твоих взыскал."},
  {"id": "ru-str-0220", "section": "service", "who": "choir", "text": "С благовониями Тебя, Христе, Никодим и благородный Иосиф / ныне по-новому предав погребению, взывали: / «Содрогнись, вся земля!»"},
  {"id": "ru-str-0221", "section": "service", "who": "choir", "text": "От всякого злого пути удержал я ноги мои, / чтобы сохранить слова Твои."},
  {"id": "ru-str-0222", "section": "service", "who": "choir", "text": "Ты зашел, Создатель светов, и с Тобою зашел свет солнца, / а творение охватывается трепетом, / провозглашая Тебя Творцом всего."},
  {"id": "ru-str-0223", "section": "service", "who": "choir", "text": "От судов Твоих не уклонился, / ибо Ты дал мне закон."},
  {"id": "ru-str-0224", "section": "service", "who": "choir", "text": "Камень обсеченный покрывает краеугольный Камень, / а смертный человек ныне Бога, как смертного скрывает во гробе. / Ужаснись земля!"},
  {"id": "ru-str-0225", "section": "service", "who": "choir", "text": "Как сладки гортани моей слова Твои, – / лучше меда устам моим."},
  {"id": "ru-str-0226", "section": "service", "who": "choir", "text": "«Взгляни на ученика, которого Ты возлюбил, и Матерь Твою, / и подай голос, Дитя Сладчайшее», – / взывала Чистая с плачем."},
  {"id": "ru-str-0227", "section": "service", "who": "choir", "text": "От заповедей Твоих я разум стяжал, / потому возненавидел всякий путь неправды."},
  {"id": "ru-str-0228", "section": "service", "who": "choir", "text": "Ты, как истинный Податель жизни, Слово, / на Кресте простертый не умертвил Иудеев, / но воскресил и их мертвецов."},
  {"id": "ru-str-0229", "section": "service", "who": "choir", "text": "Светильник ногам моим закон Твой / и свет стезям моим."},
  {"id": "ru-str-0230", "section": "service", "who": "choir", "text": "Ни красоты, ни вида не имел Ты прежде, во время страдания Твоего, Слово; / воскресши же, воссиял с преизбытком, / украсив смертных Божественными блистаниями."},
  {"id": "ru-str-0231", "section": "service", "who": "choir", "text": "Я поклялся и постановил / сохранить суды правды Твоей."},
  {"id": "ru-str-0232", "section": "service", "who": "choir", "text": "Зашел Ты плотию в землю, немеркнущий Носитель Света, / и солнце, будучи не в силах это видеть, / помрачилось в разгар полудня."},
  {"id": "ru-str-0233", "section": "service", "who": "choir", "text": "Я унижен был до предела, Господи, оживи меня по слову Твоему."},
  {"id": "ru-str-0234", "section": "service", "who": "choir", "text": "Солнце и луна вместе омраченные, Спаситель, / благожелательных рабов изображая, / облекаются в черные одежды."},
  {"id": "ru-str-0235", "section": "service", "who": "choir", "text": "Добровольные жертвы уст моих приими же благосклонно, Господи, / и судам Твоим научи меня."},
  {"id": "ru-str-0236", "section": "service", "who": "choir", "text": "«Познал в Тебе Бога сотник, хотя Ты и умер, – / как же я Тебя, Боже мой, коснусь руками? / Содрогаюсь я!» – взывал Иосиф."},
  {"id": "ru-str-0237", "section": "service", "who": "choir", "text": "Душа моя постоянно в руках Твоих, – / и закона Твоего я не забыл."},
  {"id": "ru-str-0238", "section": "service", "who": "choir", "text": "Уснул Адам, – и смерть из ребр изводит, / а Ты ныне уснув, Слово Божие, / из ребр Твоих изливаешь миру жизнь."},
  {"id": "ru-str-0239", "section": "service", "who": "choir", "text": "Устроили грешники мне западню, – / но я от заповедей Твоих не уклонился."},
  {"id": "ru-str-0240", "section": "service", "who": "choir", "text": "Уснул Ты ненадолго, и оживил умерших, / и, воскресши, воскресил / спящих от века, Благой."},
  {"id": "ru-str-0241", "section": "service", "who": "choir", "text": "Унаследовал я свидетельства Твои вовек, / ибо они – радость сердца моего."},
  {"id": "ru-str-0242", "section": "service", "who": "choir", "text": "Ты был взят от земли, но излил вино спасения, / источающая жизнь Виноградная Лоза; / прославляю Твое страдание и Крест."},
  {"id": "ru-str-0243", "section": "service", "who": "choir", "text": "Склонил я сердце моё, чтобы исполнить повеления Твои / вовек, ради воздаяния."},
  {"id": "ru-str-0244", "section": "service", "who": "choir", "text": "Как невещественные военачальники, видя Тебя, Спаситель, / обнаженным, окровавленным, осужденным / выносили дерзость распинателей?"},
  {"id": "ru-str-0245", "section": "service", "who": "choir", "text": "Законопреступников возненавидел, / а закон Твой я возлюбил."},
  {"id": "ru-str-0246", "section": "service", "who": "choir", "text": "Обрученный, но строптивейший род еврейский, / ты знал о восстановлении храма, / для чего ты осудил Христа?"},
  {"id": "ru-str-0247", "section": "service", "who": "choir", "text": "Помощник мой и заступник мой – Ты, / на слова Твои я уповал."},
  {"id": "ru-str-0248", "section": "service", "who": "choir", "text": "В плащ глумления ты облекаешь Устроителя всего, / Который утвердил небо / и украсил землю дивно."},
  {"id": "ru-str-0249", "section": "service", "who": "choir", "text": "Удалитесь от меня, творящие зло, / и буду исследовать заповеди Бога моего."},
  {"id": "ru-str-0250", "section": "service", "who": "choir", "text": "Как пеликан, уязвленный в ребра Твои, Слово, / оживил Ты детей Твоих умерших, / источив им животворные родники."},
  {"id": "ru-str-0251", "section": "service", "who": "choir", "text": "Поддержи меня по слову Твоему, и буду жить, / и не постыди меня в ожидании моём."},
  {"id": "ru-str-0252", "section": "service", "who": "choir", "text": "Прежде солнце остановил Иисус Навин, иноплеменников поражая, / но ныне Ты Сам скрылся, / низлагая начальника мрака."},
  {"id": "ru-str-0253", "section": "service", "who": "choir", "text": "Помоги мне и буду спасён, / и буду вникать в повеления Твои всегда."},
  {"id": "ru-str-0254", "section": "service", "who": "choir", "text": "Неотлучно от Отеческих недр Ты пребыл, Милосердный, / и стать человеком благоволил, / и во ад сошел, Христе."},
  {"id": "ru-str-0255", "section": "service", "who": "choir", "text": "В ничто Ты вменил всех, отступающих от повелений Твоих, / ибо неправедно помышление их."},
  {"id": "ru-str-0256", "section": "service", "who": "choir", "text": "Вознесен был Распятый, на водах повесивший землю, / и бездыханным Он в ней погребается, / и не вынося того, она сотрясается сильно."},
  {"id": "ru-str-0257", "section": "service", "who": "choir", "text": "Преступниками счел я всех грешников земли, / потому возлюбил свидетельства Твои."},
  {"id": "ru-str-0258", "section": "service", "who": "choir", "text": "«Увы Мне, о Сын», – не знавшая мужа рыдает и возглашает, – / «ведь Тебя, Кого Я надеялась видеть царем, / ныне вижу осужденным на Кресте!»"},
  {"id": "ru-str-0259", "section": "service", "who": "choir", "text": "Пригвозди страхом пред Тобою плоть мою, / ибо от судов Твоих я убоялся."},
  {"id": "ru-str-0260", "section": "service", "who": "choir", "text": "«Это Мне возвестил Гавриил, когда прилетел: / он сказал, что будет вечным / Царство Сына Моего Иисуса»."},
  {"id": "ru-str-0261", "section": "service", "who": "choir", "text": "Сотворил я суд и правду, / не предай меня обижающим меня."},
  {"id": "ru-str-0262", "section": "service", "who": "choir", "text": "«Увы, пророчество Симеона исполнено: / ибо меч Твой прошел / сквозь сердце Мое, Эммануил!»"},
  {"id": "ru-str-0263", "section": "service", "who": "choir", "text": "Прими раба Твоего ко благу, / чтобы не оклеветали меня гордые!"},
  {"id": "ru-str-0264", "section": "service", "who": "choir", "text": "Хотя бы тех устыдились вы, о Иудеи, / кого из мертвых воскресил жизни Податель, / Тот, Кого вы по зависти убили."},
  {"id": "ru-str-0265", "section": "service", "who": "choir", "text": "Изнемогли очи мои, ожидая спасения Твоего / и слова правды Твоей."},
  {"id": "ru-str-0266", "section": "service", "who": "choir", "text": "Содрогнулось солнце, увидев Свет незримый, – Тебя Христе Мой, / в гробнице скрытым и бездыханным, / и помрачило свой свет."},
  {"id": "ru-str-0267", "section": "service", "who": "choir", "text": "Сотвори с рабом Твоим по милости Твоей, / и повелениям Твоим научи меня."},
  {"id": "ru-str-0268", "section": "service", "who": "choir", "text": "Плакала горько Всенепорочная Матерь Твоя, Слово, / когда во гробе увидела Тебя, / Непостижимого и Безначального Бога."},
  {"id": "ru-str-0269", "section": "service", "who": "choir", "text": "Я раб Твой, вразуми меня, / и познаю свидетельства Твои."},
  {"id": "ru-str-0270", "section": "service", "who": "choir", "text": "Видя Умерщвление Твое, Христе, Пречистая Матерь Твоя, / горько к Тебе возглашала: / «Не задерживайся, Жизнь, среди мертвых»."},
  {"id": "ru-str-0271", "section": "service", "who": "choir", "text": "Время действовать Господу: / разрушили закон Твой."},
  {"id": "ru-str-0272", "section": "service", "who": "choir", "text": "Страшный ад затрепетал, когда увидел Тебя, / Бессмертное Солнце славы, / и отпускал узников поспешно."},
  {"id": "ru-str-0273", "section": "service", "who": "choir", "text": "Потому возлюбил я заповеди Твои / больше золота и топаза."},
  {"id": "ru-str-0274", "section": "service", "who": "choir", "text": "Великое и страшное видение созерцается ныне, Спаситель: / ибо Виновник жизни принял смерть добровольно, / желая оживить всех."},
  {"id": "ru-str-0275", "section": "service", "who": "choir", "text": "Потому ко всем заповедям Твоим я направлялся, / всякий путь неправды возненавидел."},
  {"id": "ru-str-0276", "section": "service", "who": "choir", "text": "Ты пронзаешься в ребра и пригвождаешься руками, Владыка, / язву из ребра Твоего исцеляя, / и невоздержание рук праотцев."},
  {"id": "ru-str-0277", "section": "service", "who": "choir", "text": "Дивны свидетельства Твои: / потому углубилась в них душа моя."},
  {"id": "ru-str-0278", "section": "service", "who": "choir", "text": "Прежде сына Рахили оплакали все, бывшие в доме, / ныне о Сыне Девы стал бить себя в грудь / сонм учеников с Матерью."},
  {"id": "ru-str-0279", "section": "service", "who": "choir", "text": "Явление слов Твоих / просвещает и вразумляет младенцев."},
  {"id": "ru-str-0280", "section": "service", "who": "choir", "text": "Удар рукою нанесен по лицу Христа, / рукою человека создавшего / и челюсти зверя сокрушившего."},
  {"id": "ru-str-0281", "section": "service", "who": "choir", "text": "Открыл я уста мои и привлек в себя Дух, / ибо заповедей Твоих вожделел."},
  {"id": "ru-str-0282", "section": "service", "who": "choir", "text": "В песнопениях распятие, как и погребение Твое, Христе, / все мы, верные, ныне боготворим, / избавленные от смерти Твоим погребением."},
  {"id": "ru-str-0283", "section": "service", "who": "choir", "text": "Слава, Троичен: Безначальный Боже, со-вечное Слово и Дух, / по Своей благости укрепи / скипетры властителей против врагов."},
  {"id": "ru-str-0284", "section": "service", "who": "choir", "text": "И ныне, Богородичен: Родившая Жизнь, Пренепорочная, Чистая Дева, / по Своей благости прекрати / соблазны в Церкви и даруй мир."},
  {"id": "ru-str-0285", "section": "service", "who": "rubric", "text": "И оба хора повторяют первый тропарь:"},
  {"id": "ru-str-0286", "section": "service", "who": "choir", "text": "Достойно есть прославлять Тебя, жизни Подателя, / на Кресте руки простершего / и могущество врага сокрушившего."},
  {"id": "ru-str-0287", "section": "service", "who": "rubric", "text": "Затем ектения малая, молитва 7 и возглас:"},
  {"id": "ru-str-0288", "section": "service", "who": "choir", "text": "Ибо Свят Ты, Боже наш, на престоле славы Херувимском почивающий, и Тебе славу воссылаем, со безначальным Твоим Отцом, и всесвятым и благим и животворящим Твоим Духом, ныне, и всегда, и во веки веков."},
  {"id": "ru-str-0289", "section": "service", "who": "rubric", "text": "И после каждения начинаем третью статию."},
  {"id": "ru-str-0290", "section": "service", "who": "choir", "text": "Статия третья Стих, глас 3:"},
  {"id": "ru-str-0291", "section": "service", "who": "choir", "text": "Все поколения / песнь погребению Твоему / приносят, Христе мой."},
  {"id": "ru-str-0292", "section": "service", "who": "choir", "text": "Воззри на меня и помилуй меня / по суду любящих имя Твоё."},
  {"id": "ru-str-0293", "section": "service", "who": "choir", "text": "Сняв с Древа, / Аримафеянин во гробе / Тебя погребает."},
  {"id": "ru-str-0294", "section": "service", "who": "choir", "text": "Стопы мои направь по слову Твоему, / и да не овладеет мною никакое беззаконие."},
  {"id": "ru-str-0295", "section": "service", "who": "choir", "text": "Мироносицы пришли, / миро для Тебя, Христе мой / принося с усердием."},
  {"id": "ru-str-0296", "section": "service", "who": "choir", "text": "Избавь меня от клеветы человеческой, / и сохраню заповеди Твои."},
  {"id": "ru-str-0297", "section": "service", "who": "choir", "text": "Приди, все творение, / песнопения погребальные / будем приносить Создателю."},
  {"id": "ru-str-0298", "section": "service", "who": "choir", "text": "Яви свет лица Твоего рабу Твоему / и научи меня повелениям Твоим."},
  {"id": "ru-str-0299", "section": "service", "who": "choir", "text": "Живущего, как мертвеца / миром все помажем благоразумно / вместе с мироносицами."},
  {"id": "ru-str-0300", "section": "service", "who": "choir", "text": "Источники вод излили очи мои, / ибо не сохранили закона Твоего."},
  {"id": "ru-str-0301", "section": "service", "who": "choir", "text": "Иосиф трижды блаженный, / погреби тело / Христа, жизни Подателя."},
  {"id": "ru-str-0302", "section": "service", "who": "choir", "text": "Праведен Ты, Господи, / и правы суды Твои."},
  {"id": "ru-str-0303", "section": "service", "who": "choir", "text": "Те, кого вскормил Он манной, / подвигли пяту / на Благодетеля."},
  {"id": "ru-str-0304", "section": "service", "who": "choir", "text": "Ты заповедал правду – свидетельства Твои, / и истину – твердо."},
  {"id": "ru-str-0305", "section": "service", "who": "choir", "text": "Те, кого вскормил Он манной, / Спасителю подносят / желчь вместе с уксусом."},
  {"id": "ru-str-0306", "section": "service", "who": "choir", "text": "Изнурила меня ревность по Тебе, / ибо забыли слова Твои враги мои."},
  {"id": "ru-str-0307", "section": "service", "who": "choir", "text": "О, безрассудство / и Христоубийство / убийц пророков!"},
  {"id": "ru-str-0308", "section": "service", "who": "choir", "text": "Огнем очищено слово Твоё вполне, / и раб Твой возлюбил его."},
  {"id": "ru-str-0309", "section": "service", "who": "choir", "text": "Как безумный слуга, / предал участник таинств / Бездну Премудрости."},
  {"id": "ru-str-0310", "section": "service", "who": "choir", "text": "Весьма молод я и презрен, – / повелений Твоих не забыл."},
  {"id": "ru-str-0311", "section": "service", "who": "choir", "text": "Продав Избавителя, / пленником стал / коварный Иуда."},
  {"id": "ru-str-0312", "section": "service", "who": "choir", "text": "Правда Твоя – правда вовек, / и закон Твой – истина."},
  {"id": "ru-str-0313", "section": "service", "who": "choir", "text": "Согласно Соломону, / глубокая яма / уста беззаконных Евреев."},
  {"id": "ru-str-0314", "section": "service", "who": "choir", "text": "Скорби и беды нашли меня, – / заповеди Твои – занятие моё."},
  {"id": "ru-str-0315", "section": "service", "who": "choir", "text": "На кривых путях / беззаконных Евреев / колючки и западни."},
  {"id": "ru-str-0316", "section": "service", "who": "choir", "text": "Свидетельства Твои – правда вовек; / вразуми меня, и буду жить."},
  {"id": "ru-str-0317", "section": "service", "who": "choir", "text": "Иосиф с Никодимом / по образу умерших / погребают Творца."},
  {"id": "ru-str-0318", "section": "service", "who": "choir", "text": "Воззвал я всем сердцем моим, / услышь меня, Господи, повелений Твоих взыщу."},
  {"id": "ru-str-0319", "section": "service", "who": "choir", "text": "Податель жизни, Спаситель, / слава Твоему могуществу, / ад разорившему."},
  {"id": "ru-str-0320", "section": "service", "who": "choir", "text": "Воззвал я к Тебе, спаси меня, / и сохраню свидетельства Твои."},
  {"id": "ru-str-0321", "section": "service", "who": "choir", "text": "Видя Тебя, Слово, / лежащим навзничь, / Пречистая матерински рыдала."},
  {"id": "ru-str-0322", "section": "service", "who": "choir", "text": "Раньше времени начал я и воззвал, – / на слова Твои уповал."},
  {"id": "ru-str-0323", "section": "service", "who": "choir", "text": "«О, сладкая Весна Моя, / сладчайшее Мое Дитя, / куда зашла Твоя красота?»"},
  {"id": "ru-str-0324", "section": "service", "who": "choir", "text": "Открылись очи мои до рассвета, / чтобы углубляться в слова Твои."},
  {"id": "ru-str-0325", "section": "service", "who": "choir", "text": "Плач возбуждала / Пречистая Матерь Твоя, / ибо Ты умерщвлен был, Слово."},
  {"id": "ru-str-0326", "section": "service", "who": "choir", "text": "Голос мой услышь, Господи, по милости Твоей, / по суду Твоему оживи меня."},
  {"id": "ru-str-0327", "section": "service", "who": "choir", "text": "Жены с благовониями / пришли помазать миром Христа, / Божественное Миро."},
  {"id": "ru-str-0328", "section": "service", "who": "choir", "text": "Приблизились гонящие меня беззаконно, / от закона же Твоего удалились."},
  {"id": "ru-str-0329", "section": "service", "who": "choir", "text": "Смертию смерть / Ты умерщвляешь, Боже Мой, / Божественным Твоим могуществом."},
  {"id": "ru-str-0330", "section": "service", "who": "choir", "text": "Близок Ты, Господи, / и все заповеди Твои – истина."},
  {"id": "ru-str-0331", "section": "service", "who": "choir", "text": "Введен в заблуждение обманщик, / а обольщенный избавляется / Премудростью Твоею, Боже мой,"},
  {"id": "ru-str-0332", "section": "service", "who": "choir", "text": "От начала я познал из свидетельств Твоих, / что навек Ты их основал."},
  {"id": "ru-str-0333", "section": "service", "who": "choir", "text": "На дно ада / низведен был предатель, / в колодец погибели."},
  {"id": "ru-str-0334", "section": "service", "who": "choir", "text": "Воззри на унижение моё и избавь меня, / ибо закона Твоего я не забыл."},
  {"id": "ru-str-0335", "section": "service", "who": "choir", "text": "Колючки и западни – / пути трижды несчастного / безумного Иуды."},
  {"id": "ru-str-0336", "section": "service", "who": "choir", "text": "Рассуди дело мое и избавь меня, / по слову Твоему оживи меня."},
  {"id": "ru-str-0337", "section": "service", "who": "choir", "text": "Погибают все вместе / распинатели Твои, Слово, / Сын Божий, Царь всего."},
  {"id": "ru-str-0338", "section": "service", "who": "choir", "text": "Далеко от грешных спасение, / ибо повелений Твоих не взыскали."},
  {"id": "ru-str-0339", "section": "service", "who": "choir", "text": "В колодце погибели / гибнут все вместе / люди кровожадные."},
  {"id": "ru-str-0340", "section": "service", "who": "choir", "text": "Велико сострадание Твоё, Господи, / по суду Твоему оживи меня."},
  {"id": "ru-str-0341", "section": "service", "who": "choir", "text": "Сын Божий, Царь всего, / Боже мой, Создатель мой, / как Ты принял страдание?"},
  {"id": "ru-str-0342", "section": "service", "who": "choir", "text": "Много изгоняющих меня и теснящих меня, – / от свидетельств Твоих я не уклонился."},
  {"id": "ru-str-0343", "section": "service", "who": "choir", "text": "Телица, видя Тельца, / повешенным на Древе, / восклицала."},
  {"id": "ru-str-0344", "section": "service", "who": "choir", "text": "Увидел неразумных и изнемогал, / ибо они слов Твоих не сохранили."},
  {"id": "ru-str-0345", "section": "service", "who": "choir", "text": "Тело живоносное / Иосиф погребает / с Никодимом."},
  {"id": "ru-str-0346", "section": "service", "who": "choir", "text": "Узри, что я заповеди Твои возлюбил, Господи, / по милости Твоей оживи меня."},
  {"id": "ru-str-0347", "section": "service", "who": "choir", "text": "Восклицала Дева, / проливая горячие слезы, / внутренне пронзаемая."},
  {"id": "ru-str-0348", "section": "service", "who": "choir", "text": "Начало слов Твоих – истина, / и вовек – все суды правды Твоей."},
  {"id": "ru-str-0349", "section": "service", "who": "choir", "text": "«О Свет очей Моих, / сладчайшее Мое Дитя, / как Ты ныне во гробе скрываешься?»"},
  {"id": "ru-str-0350", "section": "service", "who": "choir", "text": "Князья стали гнать меня безвинно, / но от слов Твоих убоялось сердце моё."},
  {"id": "ru-str-0351", "section": "service", "who": "choir", "text": "«Чтобы освободить Адама и Еву / Я претерпеваю это, – / не рыдай, Матерь»."},
  {"id": "ru-str-0352", "section": "service", "who": "choir", "text": "Возрадуюсь я о словах Твоих, / как находящий много добычи."},
  {"id": "ru-str-0353", "section": "service", "who": "choir", "text": "«Славлю, Сын Мой, / величайшее Твое милосердие, / из-за которого Ты это переносишь»."},
  {"id": "ru-str-0354", "section": "service", "who": "choir", "text": "Неправду возненавидел я и возгнушался ею, / закон же Твой возлюбил."},
  {"id": "ru-str-0355", "section": "service", "who": "choir", "text": "Ты был напоен уксусом / и желчью, Милосердный, / уничтожая грех древнего вкушения."},
  {"id": "ru-str-0356", "section": "service", "who": "choir", "text": "Семь раз в день восхвалил я Тебя /за суды правды Твоей."},
  {"id": "ru-str-0357", "section": "service", "who": "choir", "text": "На видном месте Ты был пригвожден, / в древности народ Твой / столпом облачным покрывавший."},
  {"id": "ru-str-0358", "section": "service", "who": "choir", "text": "Великий мир – любящим закон Твой, / и нет им преткновения."},
  {"id": "ru-str-0359", "section": "service", "who": "choir", "text": "Мироносицы, ко гробу пришедшие, / приносили благовония / Тебе, Спаситель."},
  {"id": "ru-str-0360", "section": "service", "who": "choir", "text": "Ожидал я спасения Твоего, Господи, / и заповеди Твои возлюбил."},
  {"id": "ru-str-0361", "section": "service", "who": "choir", "text": "Воскресни, Милосердный, / поднимая нас / из пропастей ада."},
  {"id": "ru-str-0362", "section": "service", "who": "choir", "text": "Сохранила душа моя свидетельства Твои, / и возлюбила их крепко."},
  {"id": "ru-str-0363", "section": "service", "who": "choir", "text": "«Восстань, жизни Податель», – / говорит, проливая слезы, / родившая Тебя Матерь."},
  {"id": "ru-str-0364", "section": "service", "who": "choir", "text": "Сохранил я заповеди Твои и свидетельства Твои, / ибо все пути мои пред Тобою, Господи."},
  {"id": "ru-str-0365", "section": "service", "who": "choir", "text": "«Поспеши восстать, Слово, / прекращая скорбь / непорочно Тебя Родившей!»"},
  {"id": "ru-str-0366", "section": "service", "who": "choir", "text": "Да приблизится моление моё пред лицо Твоё, Господи, – / по слову Твоему вразуми меня."},
  {"id": "ru-str-0367", "section": "service", "who": "choir", "text": "Небесные Силы / изумлялись в страхе, / мертвым Тебя созерцая."},
  {"id": "ru-str-0368", "section": "service", "who": "choir", "text": "Да взойдет прошение моё пред лицо Твоё, Господи, – / по слову Твоему избавь меня."},
  {"id": "ru-str-0369", "section": "service", "who": "choir", "text": "С любовию и страхом / страдания Твои почитающим / даруй избавление от согрешений."},
  {"id": "ru-str-0370", "section": "service", "who": "choir", "text": "Изольют уста мои песнь, / когда Ты научишь меня повелениям Твоим."},
  {"id": "ru-str-0371", "section": "service", "who": "choir", "text": "О, страшное и необычайное зрелище, / Слово Божие! / Как земля Тебя скрывает?"},
  {"id": "ru-str-0372", "section": "service", "who": "choir", "text": "Произнесет язык мой слова Твои, / ибо все заповеди Твои – правда."},
  {"id": "ru-str-0373", "section": "service", "who": "choir", "text": "Прежде бежит в Египет Иосиф, / неся Тебя, Спаситель, / и ныне другой Иосиф Тебя погребает."},
  {"id": "ru-str-0374", "section": "service", "who": "choir", "text": "Да будет рука Твоя во спасение мне, / ибо заповеди Твои я избрал."},
  {"id": "ru-str-0375", "section": "service", "who": "choir", "text": "Плачет и рыдает / Всечистая Матерь Твоя / о Тебе, Спаситель мой, умершем."},
  {"id": "ru-str-0376", "section": "service", "who": "choir", "text": "Возжелал я спасения Твоего, Господи, / и закон Твой – занятие моё."},
  {"id": "ru-str-0377", "section": "service", "who": "choir", "text": "Содрогаются умы / пред необычайным и повергающим в трепет / погребением Тебя, Создателя всего."},
  {"id": "ru-str-0378", "section": "service", "who": "choir", "text": "Будет жить душа моя и восхвалит Тебя, / и суды Твои помогут мне."},
  {"id": "ru-str-0379", "section": "service", "who": "choir", "text": "Окропили миром / гроб Твой мироносицы, / весьма рано пришедшие."},
  {"id": "ru-str-0380", "section": "service", "who": "choir", "text": "Заблудился я, как овца пропавшая; / взыщи раба Твоего, ибо заповедей Твоих я не забыл."},
  {"id": "ru-str-0381", "section": "service", "who": "choir", "text": "Мир – Церкви, / народу Твоему – спасение / даруй Твоим воскресением."},
  {"id": "ru-str-0382", "section": "service", "who": "choir", "text": "Слава, Троичен: О, Троица, Боже мой, – / Отец, Сын и Дух, / помилуй мiр!"},
  {"id": "ru-str-0383", "section": "service", "who": "choir", "text": "И ныне, Богородичен: Увидеть воскресение / Сына Твоего, Дева, / удостой Твоих рабов."},
  {"id": "ru-str-0384", "section": "service", "who": "choir", "text": "Тропари, глас 5"},
  {"id": "ru-str-0385", "section": "service", "who": "choir", "text": "Благословен Ты, Господи, научи меня повелениям Твоим."},
  {"id": "ru-str-0386", "section": "service", "who": "choir", "text": "Ангельский сонм изумился, / видя Тебя, Спаситель, к мертвым причтенного, / но силу смерти сокрушившего, / и Адама с Собою воздвигшего, / и от ада всех освободившего."},
  {"id": "ru-str-0387", "section": "service", "who": "choir", "text": "Благословен Ты, Господи, научи меня повелениям Твоим."},
  {"id": "ru-str-0388", "section": "service", "who": "choir", "text": "«Что вы миро слезами сострадания, / о ученицы, разбавляете?» / – Ангел, блистающий в гробнице, к мироносицам взывал, / – «осмотрите вы гробницу и познайте, / что воскрес Спаситель из гроба!»"},
  {"id": "ru-str-0389", "section": "service", "who": "choir", "text": "Благословен Ты, Господи, научи меня повелениям Твоим."},
  {"id": "ru-str-0390", "section": "service", "who": "choir", "text": "Рано утром поспешили / мироносицы ко гробу Твоему с рыданиями. / Но предстал пред ними Ангел и возгласил: / «Кончилось время рыдания, не плачьте, / но о воскресении Апостолам возвестите»."},
  {"id": "ru-str-0391", "section": "service", "who": "choir", "text": "Благословен Ты, Господи, научи меня повелениям Твоим."},
  {"id": "ru-str-0392", "section": "service", "who": "choir", "text": "Жены-мироносицы с миром пришедшие / ко гробу Твоему, Спаситель, рыдали, / тогда как Ангел им возглашал: / «Что вы к мертвым Живого причисляете? / Ведь как Бог воскрес Он из гроба»."},
  {"id": "ru-str-0393", "section": "service", "who": "choir", "text": "Слава, Троичен: Поклонимся Отцу, / и Его Сыну, и Святому Духу, / Святой Троице во едином существе, / с Серафимами восклицая: / «Свят, Свят, Свят Ты, Господи»."},
  {"id": "ru-str-0394", "section": "service", "who": "choir", "text": "И ныне, Богородичен: Жизни Подателя родив, / Ты, Дева, от греха Адама избавила, / Еве же радость вместо скорби подала; / от жизни отпавшего к ней же направил / из Тебя воплотившийся Бог и Человек."},
  {"id": "ru-str-0395", "section": "service", "who": "choir", "text": "Аллилуия, аллилуия, аллилуия, слава Тебе, Боже. (3)"},
  {"id": "ru-str-0396", "section": "service", "who": "rubric", "text": "Затем ектения малая, молитва 8 и возглас:"},
  {"id": "ru-str-0397", "section": "service", "who": "choir", "text": "Ибо Ты – Царь мира, Христе Боже наш, и Тебе славу воссылаем, со безначальным Твоим Отцом, и всесвятым и благим и животворящим Твоим Духом, ныне и всегда, и во веки веков."},
  {"id": "ru-str-0398", "section": "service", "who": "choir", "text": "Седален дня, глас 1"},
  {"id": "ru-str-0399", "section": "service", "who": "choir", "text": "Тело священное испросив у Пилата, / миром умащает и полагает его Иосиф в новом гробе / с чистым полотном и ароматами божественными. / Потому пришедшие чуть свет жены мироносицы воззвали: / «Покажи нам, Христе, / как Ты предсказал, воскресение!»"},
  {"id": "ru-str-0400", "section": "service", "who": "choir", "text": "Слава: Покажи нам, Христе, / как Ты предсказал, воскресение!"},
  {"id": "ru-str-0401", "section": "service", "who": "choir", "text": "И ныне: Изумились сонмы Ангелов, / созерцая Сидящего в недрах Отца, – / как подобно мертвому во гробе полагается Бессмертный; / Тот, Кого полки Ангелов окружают / и славят вместе с мертвыми во аде / как Создателя и Господа."},
  {"id": "ru-str-0402", "section": "service", "who": "choir", "text": "Воскресение Христово:"},
  {"id": "ru-str-0403", "section": "service", "who": "rubric", "text": "не поем, а читаем псалом 50."},
  {"id": "ru-str-0404", "section": "service", "who": "rubric", "text": "Творение преп. Космы Маиумского, Марка, епископа Идрунтского и инокини Кассии, глас 6; ирмосы поем дважды, а тропари на 12. В конце каждой песни оба хора вместе поют ирмос."},
  {"id": "ru-str-0405", "section": "service", "who": "choir", "text": "Канон, глас 6. Песнь 1 Ирмос:"},
  {"id": "ru-str-0406", "section": "service", "who": "choir", "text": "Волною морскою / Покрывшего в древности / преследователя-тирана / сокрыли под землею / дети Им спасенных; / но мы, как юные девы, / Господу воспоем: / ибо славно Он прославился."},
  {"id": "ru-str-0407", "section": "service", "who": "choir", "text": "Господи Боже мой! / Отходное песнопение / и надгробную песнь воспою Тебе, / погребением Своим входы жизни мне отворившему / и смертию смерть и ад умертвившему."},
  {"id": "ru-str-0408", "section": "service", "who": "choir", "text": "В высоте – на престоле / и внизу – во гробе / надмирные и подземные существа / созерцая Тебя, Спаситель мой, / сотрясались при умерщвлении Твоем: / ибо превыше разума Ты явился мертвым, / жизни Первоначальник."},
  {"id": "ru-str-0409", "section": "service", "who": "choir", "text": "Дабы Своею славою / все наполнить, / Ты нисшел в глубочайшие места земли; / ибо не скрылось от Тебя / естество мое, то, что у Адама, / и, погребенный, Ты обновляешь / меня, истлевшего, Человеколюбец."},
  {"id": "ru-str-0410", "section": "service", "who": "choir", "text": "Песнь 3 Ирмос:"},
  {"id": "ru-str-0411", "section": "service", "who": "choir", "text": "Тебя, на водах / повесившего всю землю без опоры, / творение увидев висящим на лобном месте, / великим ужасом охваченное, восклицало: / «Нет святого, кроме Тебя, Господи!»"},
  {"id": "ru-str-0412", "section": "service", "who": "choir", "text": "Образы погребения Твоего / Ты показал во множестве видений; / а ныне тайны Свои, Владыка, / Ты богочеловечески явил и находившимся во аде, восклицавшим: / «Нет святого, кроме Тебя, Господи!»"},
  {"id": "ru-str-0413", "section": "service", "who": "choir", "text": "Ты распростер длани / и соединил прежде разделенное; / а облечением, Спаситель, / в полотно и гроб / Ты освободил и скованных цепями, восклицавших: / «Нет святого, кроме Тебя, Господи!»"},
  {"id": "ru-str-0414", "section": "service", "who": "choir", "text": "В гробнице и за печатями / Ты, Невместимый, был удержан добровольно; / и, действительно, силу Свою / Ты божественно явил делами воспевающим: / «Нет святого, кроме Тебя, Господи, Человеколюбец!»"},
  {"id": "ru-str-0415", "section": "service", "who": "choir", "text": "Седален, глас 1 Воины, охранявшие гроб Твой, Спаситель, / стали как мертвые от блистания явившегося Ангела, / возвещавшего женам о воскресении. / Тебя мы славим, тления истребителя, / к Тебе припадаем, воскресшему из гроба, /и единому Богу нашему."},
  {"id": "ru-str-0416", "section": "service", "who": "choir", "text": "Слава, и ныне:"},
  {"id": "ru-str-0417", "section": "service", "who": "rubric", "text": "повторяем то же."},
  {"id": "ru-str-0418", "section": "service", "who": "choir", "text": "Песнь 4 Ирмос:"},
  {"id": "ru-str-0419", "section": "service", "who": "choir", "text": "На Кресте Твое божественное умаление провидя, / Аввакум в изумлении взывал: / «Ты пресек, Благой, могущество властителей, / приобщаясь к находящимся во аде, / как всесильный!»"},
  {"id": "ru-str-0420", "section": "service", "who": "choir", "text": "День седьмой Ты сегодня освятил, / который прежде благословил упокоением от дел; / ибо Ты изменяешь все, Спаситель мой, и обновляешь, / покоясь, – и к Себе привлекая."},
  {"id": "ru-str-0421", "section": "service", "who": "choir", "text": "Когда Ты силой высшей одержал победу, / душа Твоя от тела отделилась; / но то и другое расторгает / узы смерти и ада / могуществом Твоим, Слово."},
  {"id": "ru-str-0422", "section": "service", "who": "choir", "text": "Ад встретившись с Тобою, Слово, ожесточился, / видя смертного обоженным, / изъязвленным ранами и вместе – всесильным, / но погиб от страха пред этим образом."},
  {"id": "ru-str-0423", "section": "service", "who": "choir", "text": "Песнь 5 Ирмос:"},
  {"id": "ru-str-0424", "section": "service", "who": "choir", "text": "Богоявления Твоего к нам, Христе, / из сострадания происшедшего, / Исаия увидев свет немеркнущий, / от ночи бодрствуя восклицал: / «Воскреснут мертвые, / и восстанут находящиеся в гробницах, / и все, на земле живущие, возрадуются!»"},
  {"id": "ru-str-0425", "section": "service", "who": "choir", "text": "Ты обновляешь рожденных на земле, Создатель, / Сам явившись созданным из праха, / и полотно и гроб указывают, Слово, / на связанное с Тобою таинство; / ибо почтенный член совета представляет / замысел Твоего Родителя, / в Тебе величественно обновляющего меня."},
  {"id": "ru-str-0426", "section": "service", "who": "choir", "text": "Смертию Ты изменяешь смертное, / погребением – тленное; / ибо Ты неизменным пребываешь, как подобает Богу, / делая бессмертным то, что принял: / ведь ни плоть Твоя не увидела тления, Владыка, / ни душа Твоя во аде дивным образом не оставлена."},
  {"id": "ru-str-0427", "section": "service", "who": "choir", "text": "От Безбрачной происшедший и пронзенный в ребра, / Ты чрез Нее, Создатель мой, / Евы совершил восстановление, / новым Адамом став, / уснув сном животворным сверхъестественно, / и жизнь пробудив от сна и тления, / как Всесильный."},
  {"id": "ru-str-0428", "section": "service", "who": "choir", "text": "Песнь 6 Ирмос:"},
  {"id": "ru-str-0429", "section": "service", "who": "choir", "text": "Был объят, но не удержан недрами кита Иона; / ибо нося образ Тебя, пострадавшего и погребению преданного, / он вышел из зверя, как из чертога, / а к страже гроба Твоего взывал: / «Соблюдающие суетное и ложное, / Самую Милость вы оставили!»"},
  {"id": "ru-str-0430", "section": "service", "who": "choir", "text": "Ты умерщвлен был, но не разделился, Слово, / с плотью, к которой приобщился; / ибо хотя и разрушился Твой храм во время страдания, / но и тогда была едина Ипостась / Божества и плоти Твоей, / ведь в обоих естествах Ты пребываешь, один Сын, / Слово Божие, Бог и человек."},
  {"id": "ru-str-0431", "section": "service", "who": "choir", "text": "Смертоносно для людей, но не для Бога, / было падение Адама, / ибо хотя и пострадало естество плоти Твоей, созданной из праха, / но бесстрастным осталось Божество, / а тленное Ты в Себе претворил в нетленное / и явил источник нетленной жизни воскресением."},
  {"id": "ru-str-0432", "section": "service", "who": "choir", "text": "Царствует ад, но не вечно, / над родом человеческим; / ибо Ты, Могущественный, положенный во гробе, / живоначальной дланию расторг засовы смерти / и возвестил сидевшим там от века истинное избавление, / став, Спаситель, первенцем из мертвых."},
  {"id": "ru-str-0433", "section": "service", "who": "choir", "text": "Кондак, глас 6 Бездну Заключивший / лежит пред нами мертвым, / и, полотном со смирною обвитый, / в гробнице полагается как смертный – Бессмертный. / Жены же пришли помазать Его миром, / плача горько и взывая: / «Эта суббота – преблагословенна, / та самая, когда Христос уснул, / чтобы на третий день воскреснуть». Икос:"},
  {"id": "ru-str-0434", "section": "service", "who": "choir", "text": "Все Удерживающий на Кресте был возвышен, / и рыдает все творение, / видя Его обнаженным, висящим на Древе; / солнце скрыло лучи, и звезды лишились света; / земля же в великом страхе поколебалась, / море побежало и камни распались, / а многие гробницы открылись, / и восстали тела святых мужей. / Ад внизу стенает, а Иудеи замышляют оклеветать Христово воскресение, / но жены взывают: / «Эта суббота – преблагословенна, / та самая, когда Христос уснул, / чтобы на третий день воскреснуть»."},
  {"id": "ru-str-0435", "section": "service", "who": "choir", "text": "Песнь 7 Ирмос:"},
  {"id": "ru-str-0436", "section": "service", "who": "choir", "text": "Неизреченное чудо! / Избавивший благочестивых отроков в печи от пламени / во гробе мертвым, бездыханным погребается, / ко спасению нас, поющих: / «Боже, Искупитель, благословен Ты!»"},
  {"id": "ru-str-0437", "section": "service", "who": "choir", "text": "Уязвлен в сердце ад, / приняв Пронзенного копьем в ребра, / и стенает, огнем божественным поглощаемый, / ко спасению нас, поющих: / «Боже, Искупитель, благословен Ты!»"},
  {"id": "ru-str-0438", "section": "service", "who": "choir", "text": "Богат гроб! / Ведь приняв в себя / как бы уснувшего Создателя, / он явлен божественной сокровищницей жизни, / ко спасению нас, поющих: / «Боже, Искупитель, благословен Ты!»"},
  {"id": "ru-str-0439", "section": "service", "who": "choir", "text": "По закону смертных / положению во гробе / подвергается Жизнь всех / и источником воскресения его являет, / ко спасению нас, поющих: / «Боже, Искупитель, благословен Ты!»"},
  {"id": "ru-str-0440", "section": "service", "who": "choir", "text": "Единым было во аде, / и во гробе, и в Эдеме / Божество Христа, нераздельное с Отцом и Духом, / ко спасению нас поющих: / «Боже, Искупитель, благословен Ты!»"},
  {"id": "ru-str-0441", "section": "service", "who": "choir", "text": "Песнь 8 Ирмос:"},
  {"id": "ru-str-0442", "section": "service", "who": "choir", "text": "Изумись в трепете, небо, / и да потрясутся основания земли; / ибо вот, к мертвым причисляется / на высотах Живущий / и в тесном гробе помещается; / Его отроки благословляйте, / священники воспевайте, / люди превозносите во все века."},
  {"id": "ru-str-0443", "section": "service", "who": "choir", "text": "Разрушен пречистый храм, / но с Собой Он восстанавливает падшую скинию, / ибо к первому Адам второй, / на высотах Живущий, / сошел даже до внутренних хранилищ ада: / Его отроки благословляйте, священники воспевайте, / люди превозносите во все века."},
  {"id": "ru-str-0444", "section": "service", "who": "choir", "text": "Не стало дерзновения у учеников, / но отличается Аримафеянин Иосиф, / ибо мертвым и обнаженным Всевышнего Бога видя, / он испрашивает Его и погребает, восклицая: / «Отроки благословляйте, священники воспевайте, / люди превозносите во все века!»"},
  {"id": "ru-str-0445", "section": "service", "who": "choir", "text": "О необычайные чудеса! О благость! / О неизреченное терпение! / Под землею добровольно запечатывается / на высотах Живущий, / и Бог, как обманщик, ложно обвиняется: / Его отроки благословляйте, священники воспевайте, / люди превозносите во все века."},
  {"id": "ru-str-0446", "section": "service", "who": "choir", "text": "Песнь 9 Ирмос:"},
  {"id": "ru-str-0447", "section": "service", "who": "choir", "text": "Не рыдай надо Мною, Матерь, / видя во гробе Сына, / Которого Ты во чреве без семени зачала, / ибо Я воскресну и буду прославлен, / и во славе вознесу, как Бог, / непрестанно с верою и любовию / Тебя величающих."},
  {"id": "ru-str-0448", "section": "service", "who": "choir", "text": "При дивном Твоем рождестве / сверхъестественно избежав мучений, / Я была прославлена, Сын безначальный; / ныне же, видя Тебя, Боже Мой, бездыханным, мертвым, / Я мечом скорби терзаюсь страшно; / но воскресни, чтобы Мне возвеличиться."},
  {"id": "ru-str-0449", "section": "service", "who": "choir", "text": "Земля покрывает Меня по Моей воле, / но трепещут привратники ада, / видя Меня, Матерь, / облеченного в окровавленную одежду мщения, / ибо поразив врагов на Кресте, как Бог, / Я опять воскресну и возвеличу Тебя."},
  {"id": "ru-str-0450", "section": "service", "who": "choir", "text": "Да радуется творение, / да веселятся все, на земле рожденные, / ибо у ада ненавистного отнята добыча; / пусть жены с ароматами Меня встречают; / Я избавляю Адама и Еву со всем их родом, / и в третий день воскресну."},
  {"id": "ru-str-0451", "section": "service", "who": "choir", "text": "Ексапостиларий, глас 2"},
  {"id": "ru-str-0452", "section": "service", "who": "choir", "text": "Свят Господь Бог наш. (3) Стих:"},
  {"id": "ru-str-0453", "section": "service", "who": "choir", "text": "Ибо свят Господь Бог наш. Стих:"},
  {"id": "ru-str-0454", "section": "service", "who": "choir", "text": "Над всеми людьми Бог наш."},
  {"id": "ru-str-0455", "section": "service", "who": "choir", "text": "На «хвалите» стихиры на 4 Глас 2"},
  {"id": "ru-str-0456", "section": "service", "who": "choir", "text": "В сей день удерживает гроб / Держащего Своей рукою все творение; / камень покрывает / Покрывшего Своею доблестью небеса. / Жизнь спит, и ад трепещет, / и Адам от уз освобождается. / Слава промыслу Твоему, / по которому все завершив, / Ты даровал нам вечный субботний покой – / всесвятое Твое воскресение из мертвых."},
  {"id": "ru-str-0457", "section": "service", "who": "choir", "text": "Что за зрелище пред глазами? / Что за нынешнее упокоение? / Царь веков, Своим страданием все предусмотренное завершив, / во гробе бездействует, / подавая нам новый субботний покой. / Ему воззовем: / «Восстань, Боже, суди землю, / ибо Ты царствуешь во веки, / имеющий безмерно великую милость!»"},
  {"id": "ru-str-0458", "section": "service", "who": "choir", "text": "Придите, увидим Жизнь нашу, во гробе лежащую, / чтобы лежащих в могилах оживотворить. / Придите, Того, Кто от Иуды в сей день созерцая спящим, / пророчески Ему воззовем: / «Возлегши, Ты уснул как лев, / кто пробудит Тебя, Царь? / Но воскресни Своею властью, / добровольно отдавший Себя за нас, / Господи, слава Тебе!» Глас 6:"},
  {"id": "ru-str-0459", "section": "service", "who": "choir", "text": "Испросил Иосиф тело Иисуса, / и положил в новой своей гробнице: / ведь подобало Ему из гроба, / выйти, как из брачного чертога. / Сокрушивший могущество смерти, / и открывший людям врата рая, / (Господи,) слава Тебе!"},
  {"id": "ru-str-0460", "section": "service", "who": "choir", "text": "Слава, глас 6: Сей день таинственно / прообразовал великий Моисей, говоря: / «И благословил Бог день седьмой», / ибо это – благословенная суббота. / Она – упокоения день, / в который почил от всех дел Своих / Единородный Сын Божий. / Через промыслительную смерть плотию упокоившись / и вновь вернувшись к тому, чем был через воскресение, / Он даровал нам вечную жизнь, / как единственно благой и Человеколюбец."},
  {"id": "ru-str-0461", "section": "service", "who": "choir", "text": "И ныне, глас 2: Преблагословенна Ты, Богородица Дева, / ибо Воплотившимся от Тебя ад пленен, / Адам из него возвращен, / проклятие лишилось силы, / Ева освобождена, смерть умерщвлена / и мы исполнились жизни. / Потому, воспевая, взываем: / «Благословен Христос Бог, так благоволивший, слава Тебе!»"},
  {"id": "ru-str-0462", "section": "service", "who": "rubric", "text": "Славословие великое; после пения Трисвятого совершается крестный ход вокруг храма с плащаницей и Евангелием. Затем у Царских врат настоятель возглашает:"},
  {"id": "ru-str-0463", "section": "service", "who": "choir", "text": "Премудрость! Станем благоговейно!"},
  {"id": "ru-str-0464", "section": "service", "who": "choir", "text": "Тропарь, глас 2"},
  {"id": "ru-str-0465", "section": "service", "who": "choir", "text": "Благородный Иосиф, / с древа сняв пречистое тело Твое, / чистым полотном обвив и помазав благовониями / в гробнице новой положил."},
  {"id": "ru-str-0466", "section": "service", "who": "choir", "text": "Тропарь пророчества, глас 2"},
  {"id": "ru-str-0467", "section": "service", "who": "choir", "text": "Держащий всего мира концы, / благоволил Ты быть удержанным гробом, Христе, / чтобы от поглощения адом / избавить человеческое естество / и, обессмертив, оживить нас, / как Бог бессмертный."},
  {"id": "ru-str-0468", "section": "service", "who": "choir", "text": "Слава: И, обессмертив, оживить нас, как Бог бессмертный."},
  {"id": "ru-str-0469", "section": "service", "who": "choir", "text": "И ныне: Держащий всего мира концы:"},
  {"id": "ru-str-0470", "section": "service", "who": "choir", "text": "Прокимен, глас 4"},
  {"id": "ru-str-0471", "section": "service", "who": "choir", "text": "Восстань, Господи, помоги нам, / и избавь нас ради имени Твоего. Стих:"},
  {"id": "ru-str-0472", "section": "service", "who": "choir", "text": "Боже, мы ушами нашими услышали, и отцы наши возвестили нам. Пс 43:27, 2А"},
  {"id": "ru-str-0473", "section": "service", "who": "choir", "text": "Пророчества Иезекииля чтение"},
  {"id": "ru-str-0474", "section": "service", "who": "choir", "text": "Была на мне рука Господня, и вывел Он меня в Духе Господнем и поставил меня посреди поля, и оно было полно костей человеческих, и обвел меня со всех сторон вокруг них, и [вот] весьма [много] их на поверхности поля, и вот, они сухи весьма. И сказал мне: «Сын человеческий! Оживут ли кости сии?» И сказал я: «Господи (Боже) *"},
  {"id": "ru-str-0475", "section": "service", "who": "choir", "text": "! Ты знаешь это». И сказал мне: «(Сын человеческий,) изреки пророчество на кости сии; и скажешь им: Кости сухие! Выслушайте слово Господне! Так говорит (Адонаи) Господь костям сим: Вот, Я введу в вас дух жизни, и наложу на вас жилы, и подниму на вас плоть, и простру по вам кожу, и введу Дух Мой в вас, и оживете, и узнаете, что Я – Господь». И изрек я пророчество, как заповедал мне Господь. И произошел шум, в то время, как я пророчествовал; и вот, землетрясение, и сблизились кости, (кость к кости,) каждая с суставом своим. И я увидел: и вот, (появились) на них жилы, и плоть вырастала, и возникла (и простиралась) на них кожа сверху, а духа не было в них. И сказал Он мне: «Изреки пророчество к духу, сын человеческий, изреки пророчество и скажи Духу: Так говорит (Адонаи) *"},
  {"id": "ru-str-0476", "section": "service", "who": "choir", "text": "Господь: От четырех ветров приди, (Дух,) и дохни на этих мертвых, и пусть они оживут». И изрек я пророчество, согласно с тем, что Он повелел мне, и вошел в них Дух (жизни), и они ожили, и стали на ноги свои – собрание весьма многочисленное. И сказал Господь мне, говоря: «Сын человеческий! Кости эти – весь дом Израилев. (Ибо) они говорят: Сухи стали кости наши, потеряна надежда наша, мы погибли. Потому изреки пророчество, (сын человеческий,) и скажи им: Так говорит (Адонаи) *"},
  {"id": "ru-str-0477", "section": "service", "who": "choir", "text": "Господь: Вот, Я открываю гробницы ваши, и выведу вас, (народ мой,) из гробниц ваших, и введу вас в землю Израилеву. И узнаете, что Я Господь, когда Я открою могилы ваши, чтобы вывести Мне (вас) из могил (ваших,) народ Мой. И вложу Дух Мой в вас, и оживете, и помещу вас на земле вашей, и узнаете, что Я, Господь, сказал – и сделаю, говорит (Адонаи) *"},
  {"id": "ru-str-0478", "section": "service", "who": "choir", "text": "Господь». Иез 37:1–14"},
  {"id": "ru-str-0479", "section": "service", "who": "rubric", "text": "* в греч. Минее:"},
  {"id": "ru-str-0480", "section": "service", "who": "choir", "text": "Господь Господь"},
  {"id": "ru-str-0481", "section": "service", "who": "rubric", "text": ", в лучших списках текста 70 –"},
  {"id": "ru-str-0482", "section": "service", "who": "choir", "text": "Господь, в синод. –"},
  {"id": "ru-str-0483", "section": "service", "who": "choir", "text": "Господь Бог."},
  {"id": "ru-str-0484", "section": "service", "who": "choir", "text": "Прокимен, глас 7"},
  {"id": "ru-str-0485", "section": "service", "who": "choir", "text": "Восстань, Господи Боже мой, да возвысится рука Твоя, / не забудь бедных Твоих до конца. Стих:"},
  {"id": "ru-str-0486", "section": "service", "who": "choir", "text": "Буду славить Тебя, Господи, всем сердцем моим, возвещу все чудеса Твои. Пс 9:33, 2"},
  {"id": "ru-str-0487", "section": "service", "who": "choir", "text": "Апостол Послание к Коринфянам, зачало 133, 206 Братья, малая закваска заквашивает все тесто. Очистите старую закваску, чтобы быть вам новым тестом, так как вы бесквасны. Ибо и Пасха наша, Христос, был заклан. Итак, будем праздновать не со старой закваской и не с закваской порока и лукавства, но с опресноками чистоты и истины. Христос искупил нас от проклятия Закона, сделавшись за нас проклятием, потому что написано: проклят всякий, висящий на древе, чтобы на язычников благословение Авраама пришло в Иисусе Христе, чтобы обещанного Духа мы получили чрез веру. 1 Кор 5:6Б–8; Гал 3:13–14"},
  {"id": "ru-str-0488", "section": "service", "who": "choir", "text": "Аллилуия, глас 5 Стих:"},
  {"id": "ru-str-0489", "section": "service", "who": "choir", "text": "Да восстанет Бог и рассеются враги Его, и да бегут от лица Его ненавидящие Его. Стих:"},
  {"id": "ru-str-0490", "section": "service", "who": "choir", "text": "Как исчезает дым, да исчезнут, как тает воск пред лицом огня. Стих:"},
  {"id": "ru-str-0491", "section": "service", "who": "choir", "text": "Так да погибнут грешники от лица Божия, а праведники да возвеселятся. Пс 67:2, 3А, 3Б–4А"},
  {"id": "ru-str-0492", "section": "service", "who": "choir", "text": "Евангелие от Матфея, зачало 114"},
  {"id": "ru-str-0493", "section": "service", "who": "choir", "text": "На другой день, который приходится после пятницы, собрались первосвященники и фарисеи к Пилату и сказали: господин, мы вспомнили, что обманщик тот сказал, еще будучи в живых: «через три дня восстану». Повели поэтому охранять гробницу до третьего дня, чтобы ученики, придя, не украли Его, и не сказали бы народу: «восстал из мертвых»; и будет последний обман хуже первого. Сказал им Пилат: имеете стражу; идите, охраняйте, как знаете. И они пошли и охраняли гробницу, запечатав камень и приставив стражу. Мф 27:62–66 Затем ектении"},
  {"id": "ru-str-0494", "section": "service", "who": "choir", "text": "Возгласим все от всей души: Восполним утреннюю молитву нашу Господу:"},
  {"id": "ru-str-0495", "section": "service", "who": "rubric", "text": "и далее как обычно, и отпуст тот же, что на вечерне. И затем целование плащаницы, а где нет плащаницы целуем образ."},
  {"id": "ru-str-0496", "section": "service", "who": "choir", "text": "Стихира, глас 5"},
  {"id": "ru-str-0497", "section": "service", "who": "choir", "text": "Придите, прославим Иосифа, навеки памятного, / ночью к Пилату пришедшего и Жизнь всех испросившего: / «Отдай мне Сего Странника, / Который не имеет, где главу приклонить; / отдай мне Сего Странника, / Которого ученик коварный предал на смерть; / отдай мне Сего Странника, / Которого Матерь, видя висящим на Кресте, / с рыданиями взывала / и по-матерински восклицала: / «Увы Мне, Дитя Мое! Увы Мне, Свет Мой / и Жизнь Моя возлюбленная! / Ибо предсказанное в храме Симеоном в сей день сбылось: / Мое сердце меч пронзил, / но в радость о воскресении Твоем плач претвори!» / Поклоняемся страданиям Твоим, Христе. / Поклоняемся страданиям Твоим, Христе. / Поклоняемся страданиям Твоим, Христе, / и святому воскресению!"},
  {"id": "ru-str-0498", "section": "service", "who": "rubric", "text": "Первый же час поется в притворе: третий же час, шестый и девятый поются вкупе просто в притворе с блаженными во свое время."},
  {"id": "ru-str-0499", "section": "service", "who": "choir", "text": "ВО СВЯТУЮ И ВЕЛИКУЮ СУББОТУ НА ВЕЛИКОЙ ВЕЧЕРНЕ"},
  {"id": "ru-str-0500", "section": "service", "who": "choir", "text": "На «Господи воззвах» стихиры на 8. Глас 1"},
  {"id": "ru-str-0501", "section": "service", "who": "choir", "text": "Вечерние наши молитвы / приими, Святой Господи, / и даруй нам прощение грехов, / ибо Ты Один, / явивший миру воскресение."},
  {"id": "ru-str-0502", "section": "service", "who": "choir", "text": "Окружите, люди, Сион / и охватите его / и в нем воздайте славу Воскресшему из мертвых, / ибо Он – Бог наш, / искупивший нас от беззаконий наших."},
  {"id": "ru-str-0503", "section": "service", "who": "choir", "text": "Придите, люди, воспоем и поклонимся Христу, / прославляя воскресение Его из мертвых, / ибо Он – Бог наш, / от обольщения врага искупивший мир."},
  {"id": "ru-str-0504", "section": "service", "who": "choir", "text": "Страданием Твоим, Христе, / от страстей мы освободились / и воскресением Твоим / от гибели избавились. / Господи, слава Тебе!"},
  {"id": "ru-str-0505", "section": "service", "who": "choir", "text": "Преподобного Иоанна Дамаскина. Глас 8"},
  {"id": "ru-str-0506", "section": "service", "who": "choir", "text": "В сей день ад со стоном вопит: / «Лучше было бы мне / если бы я Родившегося от Марии не принял, / ибо Он, придя ко мне, / могущество мое уничтожил, / врата медные сокрушил, / а души, которыми владел я прежде, / как Бог воскресил!» / Слава, Господи, Кресту Твоему и воскресению Твоему! (2)"},
  {"id": "ru-str-0507", "section": "service", "who": "choir", "text": "В сей день ад со стоном вопит: / «Ниспровергнута моя власть: / принял я Смертного, как одного из умерших, / но удерживать Его совсем не могу / и потеряю с Ним тех, над которыми царствовал; / я имел мертвых от века, / но вот, Он пробуждает всех!» / Слава, Господи, Кресту Твоему и воскресению Твоему!"},
  {"id": "ru-str-0508", "section": "service", "who": "choir", "text": "В сей день ад со стоном вопит: / «Погибло мое могущество; / Пастырь был распят и Адама воскресил; / тех, над которыми царствовал, я лишился / и всех изверг, кого, одолев, поглотил! / Опустошил могилы Распятый: / власть смерти не имеет силы!» / Слава, Господи, Кресту Твоему и воскресению Твоему!"},
  {"id": "ru-str-0509", "section": "service", "who": "choir", "text": "Слава, глас 6: Сей день таинственно / прообразовал великий Моисей, говоря: / «И благословил Бог день седьмой», / ибо это – благословенная суббота. / Она – упокоения день, / в который почил от всех дел Своих / Единородный Сын Божий. / Через промыслительную смерть плотию упокоившись / и вновь вернувшись к тому, чем был через воскресение, / Он даровал нам вечную жизнь, / как единственно благой и Человеколюбец."},
  {"id": "ru-str-0510", "section": "service", "who": "choir", "text": "И ныне, глас 1: Всемирно славную, / от людей происшедшую и Владыку родившую / воспоем, – Марию Деву, / небесную дверь, Бесплотных песнь и верных украшение. / Ибо явилась Она небом и храмом Божества. / Она, разрушив враждебную преграду, / мир водворила и отверзла Царство. / Потому держась Её, опоры нашей веры, / имеем мы Защитником от Нее рожденного Господа. / Дерзайте же, дерзайте, люди Божии, / ибо Он победит врагов, как Всемогущий."},
  {"id": "ru-str-0511", "section": "service", "who": "rubric", "text": "Вход с Евангелием."},
  {"id": "ru-str-0512", "section": "service", "who": "choir", "text": "Свет отрадный:"},
  {"id": "ru-str-0513", "section": "service", "who": "rubric", "text": "Прокимна не произносим, но сразу:"},
  {"id": "ru-str-0514", "section": "service", "who": "choir", "text": "Премудрость."},
  {"id": "ru-str-0515", "section": "service", "who": "rubric", "text": "И начинаем чтения."},
  {"id": "ru-str-0516", "section": "service", "who": "choir", "text": "1. Бытия чтение"},
  {"id": "ru-str-0517", "section": "service", "who": "choir", "text": "В начале сотворил Бог небо и землю. Земля же была невидима и не устроена, и тьма над бездною, и Дух Божий носился над водою. И сказал Бог: «Да будет свет». И стал свет. И увидел Бог свет, что он хорош, и разделил Бог между светом и тьмою. И назвал Бог свет днем, а тьму назвал ночью. И был вечер, и было утро: день один."},
  {"id": "ru-str-0518", "section": "service", "who": "choir", "text": "И сказал Бог: «Да будет твердь посреди воды, и да будет отделять она воду от воды». И стало так. И сотворил Бог твердь, и разделил Бог между водою, (которая была) под твердью, и водою, (которая была) над твердью. И назвал Бог твердь небом. И увидел Бог, что это хорошо. И был вечер, и было утро: день второй."},
  {"id": "ru-str-0519", "section": "service", "who": "choir", "text": "И сказал Бог: «Да соберется вода, (которая) под небом, в одно собрание, и да явится суша». И стало так. И собралась вода, (которая) под небом, в собрания свои, и явилась суша. И назвал Бог сушу землею, а скопления вод назвал морями. И увидел Бог, что это хорошо."},
  {"id": "ru-str-0520", "section": "service", "who": "choir", "text": "И сказал Бог: «Да произрастит земля зелень – траву, сеющую семя по роду и по подобию её, и дерево плодовитое, приносящее плод, у которого семя его в нем по роду его на земле». И стало так. И произвела земля зелень – траву, сеющую семя по роду и по подобию её, и дерево плодовитое, приносящее плод, у которого семя его в нем, по роду его на земле. И увидел Бог, что это хорошо. И был вечер, и было утро: день третий. Быт 1:1–13"},
  {"id": "ru-str-0521", "section": "service", "who": "choir", "text": "2. Пророчества Исаии чтение"},
  {"id": "ru-str-0522", "section": "service", "who": "choir", "text": "Светись, светись, Иерусалим, ибо пришел твой свет, и слава Господня над тобою взошла. Вот, тьма покроет землю, и мрак – на народах; а над тобою воссияет Господь, и слава Его над тобою явится. И будут ходить цари в свете твоем, и народы – в сиянии твоем. Возведи вокруг очи твои и узри собранных чад твоих: (вот,) пришли сыны твои издалека, и дочери твои будут на плечах принесены. Тогда увидишь, и возрадуешься, и устрашишься, и изумишься сердцем, ибо перейдет к тебе богатство моря, и племен, и народов. И придут к тебе стада верблюдов, и покроют тебя верблюды из Мадиама и Гефы; все они из Савы придут, неся золото и ладан, принесут и камень драгоценный, и спасение Господне будут благовествовать. И все овцы Кидарские будут собраны к тебе, и овны Навеофские придут к тебе; и вознесены будут жертвы благоугодные на жертвенник Мой, и дом молитвы Моей Я прославлю. Кто эти, (которые) как облака летят, и как голуби с птенцами (ко Мне)? Меня ожидают острова и корабли Фарсисские – среди первых, чтобы привезти детей твоих издалека и серебро и золото их с ними, и это – ради святого имени Господа, и ради того, что славен Святой Израилев. И будут строить сыны иноплеменников стены твои, и цари их – предстоять тебе; ибо во гневе Моем Я поражал тебя, и по милости возлюбил тебя. И отворены будут врата твои постоянно, днем и ночью, (и) не будут затворяться, чтобы ввести к тебе силу народов и царей их приводимых. Ибо народы и цари, которые не будут служить тебе, погибнут, и такие народы совершенно запустеют. И слава Ливана к тебе придет в кипарисе, и сосне, и кедре вместе, чтобы прославить место святое Мое; и место ног Моих Я прославлю. И придут к тебе в страхе сыновья смиривших тебя и раздраживших тебя, и преклонятся к следам ног твоих все, раздражившие тебя, и ты будешь назван городом Господа, Сионом Святого Израилева. За то, что ты был оставлен и ненавидим, и не было помощника (тебе), Я [и] сделаю тебя радостью вечною, весельем родам родов. И будешь питаться молоком народов, и богатство царей вкусишь, и узнаешь, что Я – Господь, спасающий тебя, и избавляющий тебя – Бог Израилев. Ис 60:1–16"},
  {"id": "ru-str-0523", "section": "service", "who": "choir", "text": "3. Исхода чтение"},
  {"id": "ru-str-0524", "section": "service", "who": "choir", "text": "Сказал Господь Моисею и Аарону в земле Египетской, говоря: «Месяц этот для вас начало месяцев, первый он для вас между месяцами года. Скажи всему собранию сынов Израилевых, говоря: В десятый день месяца сего пусть они возьмут себе каждый агнца по домам их родов, каждый – по агнцу на дом; если же так немного будет людей в доме, что не довольно на агнца, пусть возьмет с собой соседа, ближнего к нему; по числу душ каждый, чтобы хватило ему, рассчитает на агнца. Агнец совершенный, мужеского пола, без порока, (и) однолетний будет у вас; из ягнят или из козлят его возьмите. И будет он у вас хранится до четырнадцатого дня месяца сего: и заколет его всё множество собрания сынов Израилевых, к вечеру, и возьмут от крови, и нанесут на два косяка и на перекладину дверей в домах, где будут есть его; и съедят мясо в эту ночь, испеченное на огне, и опресноки с горькими травами будут есть. Не будете есть от него ни сырого, ни сваренного в воде, но испеченное на огне, голову с ногами и внутренностями; не оставьте от него до утра и кость не сокрушите у него, но остающееся от него до утра в огне сожжете. И будете так есть его: чресла ваши препоясаны, и обувь (ваша) на ногах ваших и посохи (ваши) в руках ваших, и будете есть его с поспешностью: это – Пасха Господня». Исх 12:1–11"},
  {"id": "ru-str-0525", "section": "service", "who": "choir", "text": "4. Пророчества Ионы чтение"},
  {"id": "ru-str-0526", "section": "service", "who": "choir", "text": "Было слово Господне к Ионе, сыну Амафиину, гласящее: «Встань и пойди в Ниневию, город великий, и проповедуй в нём, ибо взошел вопль злодейства его ко Мне». И встал Иона, чтобы бежать в Фарсис от лица Господня, и сошел в Иоппию, и нашел корабль, идущий в Фарсис, и отдал свою плату за провоз, и взошел на него, чтобы уплыть с ними в Фарсис от лица Господня. Но Господь воздвиг на море ветер сильный, и сделалась буря великая на море, и корабль был в опасности крушения. И устрашились корабельщики, и взывали каждый к богу своему, и выбросили в море вещи, которые были на корабле, чтобы облегчить его от них; Иона же сошел во внутренность корабля, и спал (там), и храпел. И подошел к нему начальник корабля и сказал ему: «Что ты храпишь? Встань и призывай Бога твоего, чтобы спас нас Бог и мы не погибли». И сказал каждый ближнему своему: «Пойдемте, бросим жребии и узнаем, за кого постигает нас эта беда. И бросили жребии, и пал жребий на Иону. И сказали ему: «Объяви нам, за кого на нас эта беда? (И) какое твоё занятие? И откуда идешь и куда направляешься? И из какой ты страны, и из какого народа?» И сказал он им: «Я – раб Господень, и Господа, Бога небесного, я чту, Который сотворил море и сушу». И устрашились те мужи страхом великим, и сказали ему: «Что ты это сделал?» Ибо узнали те мужи, что от лица Господа он бежал, о чем он сам объявил им. И сказали ему: «Что нам сделать с тобою, чтобы море утихло для нас?» Ибо море вздымалось и еще больше поднимало волнение. И сказал им Иона: «Возьмите меня и бросьте меня в море, и утихнет море для вас, ибо я знаю, что ради меня постигает вас эта великая буря». И силились те мужи повернуть к земле, но не могли, потому что море вздымалось и еще больше поднималось против них. И воззвали они к Господу и сказали: «Никак да не погибнем, Господи, за душу человека сего, и да не возложишь на нас кровь праведную; ибо Ты, Господи, как хотел, соделал!» И взяли Иону и бросили его в море, и унялось море от волнения своего. И устрашились те мужи Господа страхом великим, и принесли жертву Господу, и дали обеты. И повелел Господь киту великому поглотить Иону; и был Иона во чреве кита три дня и три ночи. И помолился Иона Господу, Богу своему, из чрева кита и сказал:"},
  {"id": "ru-str-0527", "section": "service", "who": "choir", "text": "«Возопил я в скорби моей к Господу, Богу моему, и Он услышал меня; из чрева ада вопль мой: Ты услышал голос мой. Ты отринул меня в глубины, в сердце моря, и реки окружили меня; все валы Твои и волны Твои прошли надо мною. И я сказал: Отвергнут я от очей Твоих. Придётся ли мне ещё взглянуть на храм святой Твой? Разлилась вокруг меня вода до души моей, окружила меня бездна глубочайшая. Погрузилась голова моя в расселины гор, сошёл я в землю, чьи засовы – преграды вечные. Но да взойдёт от гибели жизнь моя, к Тебе, Господи, Боже мой! Когда оставляла меня душа моя, вспомнил я Господа, и да придет к Тебе молитва моя, в храм святой Твой! Соблюдающие суетное и ложное милость свою оставили, я же со гласом хвалы и славословия принесу жертву Тебе, всё, что обещал, воздам Тебе, о спасении моём – Господу!» И повелел Господь киту, и он выбросил Иону на сушу."},
  {"id": "ru-str-0528", "section": "service", "who": "choir", "text": "И было вторично к Ионе слово Господне, гласящее: «Встань и пойди в Ниневию, город великий, и проповедуй в нём, по прежнему слову, которое Я сказал тебе». И встал Иона и пошел в Ниневию, как сказал ему Господь; Ниневия же была город великий у Бога, примерно как путь, проходимый за три дня. И начал Иона входить в город, примерно на переход одного дня, и провозглашал, и говорил: «Еще три дня и Ниневия будет ниспровергнута!» И поверили мужи Ниневийские Богу, и объявили пост, и оделись во вретища, от большого из них до малого. И дошло это слово до царя Ниневии, и встал он с престола своего, и снял одеяние своё с себя, и оделся во вретище, и сел на пепле. И провозглашено было и сказано в Ниневии от царя и от вельмож его, говоривших: «Ни люди, ни скот, ни волы, ни овцы пусть (ничего) не вкушают, не пасутся и воды не пьют» И облеклись во вретища люди и скот и воззвали к Богу усердно, и отвратился каждый от пути своего злого и от неправды, что на руках их, говоря: «Кто знает, не передумает ли Бог, и не примет ли мольбы, и не отвратится ли от яростного гнева Своего, и мы не погибнем?» И увидел Бог дела их, что они отвратились от путей своих злых, и пожалел Бог о бедствии, о котором сказал, что сделает им, и не сделал."},
  {"id": "ru-str-0529", "section": "service", "who": "choir", "text": "И удручен был Иона скорбью великой и смущен. И помолился он Господу и сказал: «О, Господи! Не это ли слова мои, (которые сказал) я, когда был еще в земле моей? Потому я и поспешил бежать в Фарсис, ибо знал, что Ты милостив и сострадателен, долготерпелив и многомилостив и сожалеешь о бедствиях (человеческих). И ныне, Владыка Господи, возьми душу мою от меня, ибо лучше мне умереть, нежели жить». И сказал Господь Ионе: «Ты опечален так сильно?» И вышел Иона из города, и сел напротив города, и сделал себе навес, и сел под ним в тени, доколе не увидит, что будет с городом. И повелел Господь Бог тыкве, и она поднялась над головою Ионы, чтобы быть тенью над головою его и покрывать его от бедствий его; и возрадовался Иона о тыкве радостью великою. И повелел Бог червю ранним утром на следующий день, и повредил он тыкву, и она засохла. И было вместе с восходом солнца: и повелел Бог ветру знойному, палящему, и поразило солнце голову Ионы, и он впал в малодушие, и отрекался от души своей, и сказал: «Лучше мне умереть, нежели жить». И сказал Господь Бог Ионе: «Сильно ли ты опечален о тыкве?» Он сказал: «Сильно опечален я, даже до смерти». И сказал Господь: «Ты пожалел о тыкве, над которой ты не пострадал и не возрастил ее, которая за ночь выросла и за ночь погибла: А Мне ли не пощадить Ниневии, города великого, в котором обитает более двенадцати мириад человек, которые не знают ни правой руки своей, ни левой, и множество скота?» Ион 1:1–16; 2:1–11; 3:1–10; 4:1–11"},
  {"id": "ru-str-0530", "section": "service", "who": "choir", "text": "5. Иисуса Навина чтение"},
  {"id": "ru-str-0531", "section": "service", "who": "choir", "text": "Стали сыны Израилевы станом в Галгалах и совершили Пасху в четырнадцатый день [первого] месяца с вечера к западу от Иерихона, [на той стороне Иордана], на равнинах; и вкусили от хлеба земли (той) [наутро Пасхи]: опресноки и новые зерна. В тот день прекратила падать манна, после того, как они поели от хлеба той земли, и больше не было у сынов Израилевых манны, но они собрали урожай земли Финикийской в тот год. И случилось, когда был Иисус у Иерихона, и поднял глаза свои, он увидел человека, стоящего перед ним, и меч его обнаженный в руке его. И, подойдя, Иисус сказал ему: «Наш ли ты, или из противников (наших)?» Он же сказал ему: «Я верховный полководец воинства Господня, ныне прибыл (сюда)». И Иисус пал лицом своим на землю, и поклонился (ему) и сказал [ему]: «Владыка! Что приказываешь своему рабу?» И сказал верховный полководец Господень Иисусу: «Сними обувь с ног твоих, ибо место, на котором ты стоишь, свято». И сделал Иисус так. Ис Нав 5:10–15"},
  {"id": "ru-str-0532", "section": "service", "who": "choir", "text": "6. Исхода чтение"},
  {"id": "ru-str-0533", "section": "service", "who": "choir", "text": "Поднявшись из Сокхофа, сыны Израилевы расположились станом в Офоме, близ пустыни. Бог же шел пред ними днем в столпе облачном, чтобы показывать им путь, а ночью в столпе огненном, [чтобы светить им]. (И) не исчезал столп облачный днем и столп огненный ночью пред лицом всего народа. И сказал Господь Моисею, говоря: «Скажи сынам Израилевым, и пусть они, повернув, расположатся станом перед селением, между Магдолом и между морем, напротив Веел-Сепфона; в виду его поставишь стан у моря. И скажет фараон народу своему: Эти сыны Израилевы блуждают в земле сей, ибо заперла их пустыня. А Я ожесточу сердце фараона, и он погонится им вслед, и явлю славу Мою на фараоне, и на всем войске его, и узнают все Египтяне, что Я Господь». И сделали так."},
  {"id": "ru-str-0534", "section": "service", "who": "choir", "text": "И возвещено было царю Египетскому, что бежал народ. И обратилось сердце фараона и слуг его против народа, и они сказали: «Что это мы сделали, отпустив сынов Израилевых, чтобы не быть им рабами у нас?» Запряг же фараон колесницы свои и весь народ свой собрал с собою; и взял шестьсот колесниц отборных, и всю конницу Египетскую, и начальников над всеми ими. И ожесточил Господь сердце фараона, царя Египетского (и слуг его), и он погнался за сынами Израилевыми; сыны же Израилевы уходили под рукою высокою. И погнались Египтяне за ними, и нашли их расположившимися станом у моря; – и вся конница, и колесницы фараона, и всадники, и войско его, – перед селением, напротив Веел-Сепфона."},
  {"id": "ru-str-0535", "section": "service", "who": "choir", "text": "И Фараон приближался. И, возведя глаза свои, сыны Израилевы видят: и вот, Египтяне расположились станом за ними. И устрашились весьма, и возопили сыны Израилевы к Господу, и сказали Моисею: «Оттого, что нет гробов в Египте, ты вывел нас, чтобы умертвить в пустыне? Что это ты сделал с нами, выведя нас из Египта? Не таково ли было слово, что мы сказали тебе (в Египте), говоря: Оставь нас, чтобы нам быть рабами Египтянам? Ибо лучше нам быть рабами Египтянам, чем умереть в этой пустыне!» Но Моисей сказал народу: «Не бойтесь! Стойте – и взирайте на спасение от Господа, которое Он совершит для вас в сей день: ведь так, как вы увидели Египтян сегодня, больше уже не увидите их на вечные времена. Господь будет сражаться за вас, а вы – хранить безмолвие»."},
  {"id": "ru-str-0536", "section": "service", "who": "choir", "text": "Сказал же Господь Моисею: «Что ты вопиешь ко Мне? Скажи сынам Израилевым, и пусть они отправляются; а ты подними жезл твой и простри руку твою на море, и раздели его, и пусть войдут сыны Израилевы в середину моря по суше. И вот, Я ожесточу сердце фараона, [и слуг его,] и всех Египтян, и они войдут вслед за ними; и явлю славу Мою на фараоне, и на всем войске его, и на колесницах, и на всадниках его. И узнают все Египтяне, что Я Господь, когда Я буду являть славу Мою на фараоне, и на колесницах, и на всадниках его». И двинулся Ангел Божий, шедший пред станом сынов Израилевых, и пошел сзади (их); двинулся же и столп облачный от лица их и стал позади их; и вошел между станом Египтян и между станом сынов Израилевых, и стал, и сделался тьмой и мраком. И прошла ночь; и не сблизились они друг с другом за всю ночь. И простер Моисей руку свою на море, и гнал Господь море сильным южным ветром всю ночь и сделал море сушею, и расступилась вода. И вошли сыны Израилевы в середину моря по суше: и была вода им стеною справа и стеною слева. Египтяне же погнались, и вошли вслед за ними, – и вся конница фараона, и колесницы, и всадники, – в средину моря."},
  {"id": "ru-str-0537", "section": "service", "who": "choir", "text": "Было же в утреннюю стражу: и воззрел Господь на стан Египтян из столпа огненного и облачного и привел в смятение стан Египтян; и связал оси у колесниц их, и они вели их с усилием. И сказали Египтяне: «Побежим от лица Израиля, потому что Господь сражается за них против Египтян». И сказал Господь Моисею: «Простри руку твою на море, и пусть возвратится вода и покроет Египтян, придя и на колесницы, и на всадников». Моисей же простер руку свою на море, и возвратилась вода к наступлению дня на место; а Египтяне побежали навстречу воде. И низверг Господь Египтян в середину моря. И, вернувшись назад, вода покрыла колесницы, и всадников, (и возниц,) и всю силу фараона, вошедших вслед за ними в море; и не осталось из них ни одного. Сыны же Израилевы прошли по суше среди моря: вода же была им стеною справа и стеною слева. И избавил Господь Израиль в день тот из руки Египтян, и увидели (сыны) Израилевы Египтян мертвыми на берегу моря. Увидел же Израиль руку великую: что сделал Господь с Египтянами. И убоялся народ Господа, и поверили Богу и Моисею, служителю Его. Тогда воспел Моисей и сыны Израилевы песнь сию Господу, и сказали, (говоря):"},
  {"id": "ru-str-0538", "section": "service", "who": "choir", "text": "Песнь Моисея"},
  {"id": "ru-str-0539", "section": "service", "who": "reader", "text": "Воспоём Господу."},
  {"id": "ru-str-0540", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0541", "section": "service", "who": "reader", "text": "Коня и всадника ввергнул в море. Воспоём Господу."},
  {"id": "ru-str-0542", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0543", "section": "service", "who": "choir", "text": "Помощник и Покровитель стал мне спасением. Воспоём Господу."},
  {"id": "ru-str-0544", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0545", "section": "service", "who": "choir", "text": "Он – Бог мой, и прославлю Его, Бог отца моего, и превознесу Его. Воспоём Господу."},
  {"id": "ru-str-0546", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0547", "section": "service", "who": "choir", "text": "Господь, сокрушающий в битвах, Господь – имя Ему. Колесницы фараона и войско его ввергнул Он в море. Воспоём Господу."},
  {"id": "ru-str-0548", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0549", "section": "service", "who": "choir", "text": "Отборных конных военачальников потопил в Красном море. Воспоём Господу."},
  {"id": "ru-str-0550", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0551", "section": "service", "who": "choir", "text": "Пучиною покрыл их, они погрузились в глубину, как камень. Воспоём Господу."},
  {"id": "ru-str-0552", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0553", "section": "service", "who": "choir", "text": "Десница Твоя, Господи, прославилась силою. Воспоём Господу."},
  {"id": "ru-str-0554", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0555", "section": "service", "who": "choir", "text": "Правая рука Твоя, Господи, сломила врагов, и множеством славы Твоей Ты сокрушил противников. Воспоём Господу."},
  {"id": "ru-str-0556", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0557", "section": "service", "who": "choir", "text": "Послал гнев Твой, он пожрал их, как солому, и духом ярости Твоей расступилась вода. Воспоём Господу."},
  {"id": "ru-str-0558", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0559", "section": "service", "who": "choir", "text": "Застыли воды, как стена, застыли и волны посреди моря. Воспоём Господу."},
  {"id": "ru-str-0560", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0561", "section": "service", "who": "choir", "text": "Сказал враг: «Погонюсь, настигну, разделю добычу, насыщу душу мою, убью мечом моим, господствовать будет рука моя». Воспоём Господу."},
  {"id": "ru-str-0562", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0563", "section": "service", "who": "choir", "text": "Ты послал дух Твой, покрыло их море, погрузились они, как свинец, в воде великой. Воспоём Господу."},
  {"id": "ru-str-0564", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0565", "section": "service", "who": "choir", "text": "Кто подобен Тебе среди богов, Господи? Кто подобен Тебе, прославленный среди святых, дивный в славе, творящий чудеса? Воспоём Господу."},
  {"id": "ru-str-0566", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0567", "section": "service", "who": "choir", "text": "Ты простер десницу Твою, – поглотила их земля. Ты повёл по правде Твоей этот народ Твой, который Ты искупил. Воспоём Господу."},
  {"id": "ru-str-0568", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0569", "section": "service", "who": "choir", "text": "Призвал силою Твоею во обитель святую Твою. Услышали народы, и разгневались, муки объяли жителей Филистимских. Воспоём Господу."},
  {"id": "ru-str-0570", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0571", "section": "service", "who": "choir", "text": "Тогда заспешили вожди Эдома и князья Моавитян, объял их трепет, изнемогли все жители Ханаана. Воспоём Господу."},
  {"id": "ru-str-0572", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0573", "section": "service", "who": "choir", "text": "Да нападёт на них страх и трепет; от величия мышцы Твоей да станут они, как камень. Воспоём Господу."},
  {"id": "ru-str-0574", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0575", "section": "service", "who": "choir", "text": "Доколе не пройдёт народ Твой, Господи, доколе не пройдёт народ Твой сей, который Ты приобрёл. Воспоём Господу."},
  {"id": "ru-str-0576", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0577", "section": "service", "who": "choir", "text": "Введи и насади их на горе наследия Твоего, в готовое жилище Твоё, которое устроил Ты, Господи, святыню, Господи, которую приготовили руки Твои. Воспоём Господу."},
  {"id": "ru-str-0578", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0579", "section": "service", "who": "choir", "text": "Господь царствует вечно: и навек, и дальше. Когда вошел конь фараона с колесницами и всадниками в море, и навёл на них Господь воду морскую. Воспоём Господу."},
  {"id": "ru-str-0580", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0581", "section": "service", "who": "choir", "text": "Сыны же Израилевы прошли по суше посреди моря. Воспоём Господу."},
  {"id": "ru-str-0582", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0583", "section": "service", "who": "choir", "text": "Слава Отцу, и Сыну, и Святому Духу! Воспоём Господу."},
  {"id": "ru-str-0584", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0585", "section": "service", "who": "choir", "text": "И ныне, и всегда, и во веки веков. Аминь. Воспоём Господу."},
  {"id": "ru-str-0586", "section": "service", "who": "choir", "text": "Ибо славно Он прославился."},
  {"id": "ru-str-0587", "section": "service", "who": "rubric", "text": "Чтец (поёт):"},
  {"id": "ru-str-0588", "section": "service", "who": "reader", "text": "Ибо славно Он прославился. Исх 13:20–15:19"},
  {"id": "ru-str-0589", "section": "service", "who": "reader", "text": "7. Пророчества Софонии чтение"},
  {"id": "ru-str-0590", "section": "service", "who": "reader", "text": "Так говорит Господь: Подожди Меня до дня восстания Моего во свидетельство, (ибо суд Мой – на сборища племен, чтобы привлечь царей, чтобы излить на них гнев Мой, весь гнев ярости Моей, потому что огнем ревности Моей истреблена будет вся земля;) ибо тогда обращу у народов язык к роду его, чтобы все призывали имя Господне, служили Ему под ярмом единым. От пределов рек Эфиопии Я приму умоляющих Меня, [сыны] рассеянных (Моих) принесут жертвы Мне. В тот день ты не будешь в стыде от всех обычаев твоих, какими проявил нечестие против Меня; ибо тогда Я удалю от тебя презрительную дерзость твою, и уже не будешь больше величаться на святой горе Моей. Но оставлю среди тебя народ кроткий и смиренный, и будут благоговеть пред именем Господним остатки Израиля. И не сделают они неправды, и не скажут суетного, и не найдется в устах их языка коварного, ибо сами будут пастись и упокоятся, и не будет устрашающего их. Радуйся безмерно, дочь Сиона! Провозглашай, дочь Иерусалима! Веселись и наслаждайся от всего сердца своего, дочь Иерусалима! Устранил Господь преступления твои, искупил тебя из руки врагов твоих! Господь, Царь Израилев – посреди тебя: больше ты не увидишь зла. Соф 3:8–15"},
  {"id": "ru-str-0591", "section": "service", "who": "reader", "text": "8. Третьей книги Царств чтение"},
  {"id": "ru-str-0592", "section": "service", "who": "reader", "text": "Было к Илии слово Господне, гласящее: Встань и пойди в Сарепту Сидонскую, и поселишься там; (ибо) вот, Я повелеваю там женщине-вдове кормить тебя. И встал он, и пошел в Сарепту (Сидонскую), и пришел к воротам города: и вот, там женщина-вдова собирала дрова. И закричал ей вслед Илия, и сказал ей: «Возьми-ка мне немного воды в сосуде, и я попью». И пошла она, чтобы взять; и закричал вслед ей Илия, и сказал ей: «Захвати же для меня и кусок хлеба в руку свою, (чтобы мне поесть)». И сказала женщина: «Жив Господь, Бог твой! Нет у меня печеного; но только горсть муки в водоносе и немного масла в кувшине; и вот, наберу я два поленца, и приду, и приготовлю это для себя и для детей моих, и съедим (это), и умрем. И сказал ей Илия: «Не бойся, пойди и сделай по слову своему; но сперва приготовь для меня из этого маленький хлебец, и принесешь мне; а себе и детям своим сделаешь позже; ибо так говорит Господь, Бог Израилев: В водоносе мука не истощится, и в кувшине масло не убудет до того дня, когда Господь даст дождь на землю». И пошла женщина, и сделала по слову Илии, (и дала ему); и кормилась сама, и он, и дети её. И c того дня в водоносе мука не истощалась, и в кувшине масло не убывало, по слову Господа, которое Он изрек рукою Илии."},
  {"id": "ru-str-0593", "section": "service", "who": "reader", "text": "И было после того: заболел сын той женщины, хозяйки дома; и была болезнь его весьма сильна, покуда не прекратилось у него дыхание (его). И сказала [женщина] Илии: «Что мне и тебе, человек Божий? Ты вошел ко мне напомнить неправды мои и умертвить сына моего». И сказал Илия женщине: «Дай мне сына твоего». И взял его с лона её, и отнес его наверх, в ту горницу, в которой сам жил, и положил его на постель свою. И воззвал Илия к Господу и сказал: «Увы мне, Господи, Свидетель вдовы, у которой я пребываю! Ты причинил ей зло, умертвив сына её!» И подул он на отрока трижды, и призвал Господа, и сказал: «Господи, Боже мой! Пусть же возвратится душа этого отрока в него!» И стало так. И закричал отрок, и свел он его из горницы в дом, и отдал его матери его. И сказал Илия: «Смотри, жив сын твой». И сказала та женщина Илии: «Вот, я узнала, что ты – человек Божий, и что слово Господне в устах твоих истинно». 3 Цар 17:8–23"},
  {"id": "ru-str-0594", "section": "service", "who": "reader", "text": "9. Пророчества Исаии чтение"},
  {"id": "ru-str-0595", "section": "service", "who": "reader", "text": "Да возрадуется душа моя о Господе, ибо Он облек меня в ризу спасения, и одеждою радости одел меня, как на жениха возложил на меня венец, и как невесту украсил меня нарядом. И как земля, производящая цветы свои, и как сад семенам своим дает прорасти, так Господь – (Господь) возрастит правду и ликование пред всеми народами. Ради Сиона не промолчу, и ради Иерусалима не успокоюсь, доколе не выйдет, как свет, правда Моя, а спасение Мое как светильник не возгорится. И увидят народы правду твою, и [все] цари – славу твою; и назовут тебя именем твоим новым, тем, которое наименует Господь. И будешь венцом красоты в руке Господа и диадемою Царства в руке Бога твоего. И больше не будешь называться «Оставленной», и земля твоя не будет уже называться «Пустынею», ведь дано будет тебе имя: «Желание Моё», а земле твоей – «Обитаемая», ибо будет Господь благоволить к тебе, и земля твоя заселится. И как юноша, живущий с девою, так будут обитать с тобою сыны твои. И будет: так же, как жених возрадуется о невесте, так возрадуется Господь о тебе. Ис 61:10–11; 62:1–5"},
  {"id": "ru-str-0596", "section": "service", "who": "reader", "text": "10. Бытия чтение"},
  {"id": "ru-str-0597", "section": "service", "who": "reader", "text": "Было после этих событий: Бог испытывал Авраама и сказал ему: «Авраам, Авраам!» И сказал он: «Вот я». И сказал: «Возьми сына твоего возлюбленного, которого ты любишь, Исаака; и пойди в землю высокую и вознеси его там во всесожжение на одной из гор, о которых Я скажу тебе. Авраам же, встав рано утром, оседлал ослицу свою, и взял с собою двух отроков и Исаака, сына своего. И, наколов дров для всесожжения, встал и пошел, и пришел на место, о котором сказал ему Бог, в день третий. И, воззрев очами cвоими, увидел Авраам то место издалека. И сказал Авраам отрокам своим: «Посидите здесь с ослицей, а я и мальчик пройдем до туда, и, поклонившись, возвратимся к вам». И взял Авраам дрова для всесожжения, и возложил на Исаака, сына своего; и взял в руки огонь и нож, и пошли двое вместе. Сказал же Исаак Аврааму, отцу своему: «Отец!» Он отвечал: «Что, дитя мое?» Он же сказал: «Вот огонь и дрова, где же овца для всесожжения?» И сказал Авраам: «Бог усмотрит Себе овцу для всесожжения, дитя мое». И совершив путь оба вместе, пришли они на место, о котором сказал ему Бог; и построил там Авраам жертвенник, и положил дрова, и связав Исаака, сына своего, положил его на жертвенник поверх дров. И простер Авраам руку свою, чтобы взять нож и заколоть сына своего. И позвал его Ангел Господень с неба и сказал: «Авраам! Авраам!» Он же сказал: «Вот я». И сказал: «Не налагай руки твоей на мальчика и не делай ему ничего, ибо теперь Я узнал, что боишься ты Бога и не пощадил сына своего возлюбленного для Меня». И, воззрев Авраам очами своими, увидел: и вот, один овен, запутавшийся в растении «Савек» рогами. И пошел Авраам, и взял овна, и вознес его во всесожжение вместо Исаака, сына своего. И нарек Авраам имя месту тому: «Господь усмотрел», – так что говорят по сей день: «На горе Господь явился». И позвал Ангел Господень Авраама вторично с неба, говоря: «Мною Я поклялся, говорит Господь: из-за того, что ты сделал это дело, и не пощадил сына своего возлюбленного для Меня, Я в самом деле благословляя благословлю тебя и умножая умножу семя твоё, как звезды небесные и как песок на берегу моря; и унаследует семя твоё города противников; и благословятся в семени твоем все племена земли за то, что ты послушался гласа Моего». Быт 22:1–18"},
  {"id": "ru-str-0598", "section": "service", "who": "reader", "text": "11. Пророчества Исаии чтение"},
  {"id": "ru-str-0599", "section": "service", "who": "reader", "text": "Дух Господень на Мне: из-за того Он помазал Меня; благовествовать нищим послал Меня, исцелить сокрушенных сердцем; провозгласить пленным освобождение и слепым прозрение, объявить год Господень благоприятный и день воздаяния, утешить всех скорбящих, что дастся скорбящим Сиона слава вместо пепла; помазание радости – скорбящим; одеяние славы – вместо духа небрежения, и будут они названы отпрысками правды, насаждением Господа к славе. И застроят пустыни вечные; места, опустошенные прежде, восстановят и обновят города опустелые, опустошенные на много родов. И придут иноплеменники пасти овец твоих, и чужеземцы будут земледельцами и виноградарями (вашими). Вы же священниками Господа будете названы: «служители Бога (вашего» – будет сказано вам); мощь народов поглотите и в богатстве их дивными явитесь. Так во второй раз они наследуют землю (свою), и радость вечная над главою их. Ибо Я – Господь, любящий правду и ненавидящий похищенное с неправдою; и дам труд их праведным, и завет вечный заключу с ними. И известно будет среди племен семя их, и потомки их – между народами; всякий, видящий их, узнает их, что они семя, благословенное Богом, и они радостью возрадуются о Господе. Ис 61:1–9"},
  {"id": "ru-str-0600", "section": "service", "who": "reader", "text": "12. Четвёртой книги Царств чтение"},
  {"id": "ru-str-0601", "section": "service", "who": "reader", "text": "Был день, и пришел Елисей в Соман. И там была знатная женщина, и удержала она его у себя – вкусить хлеба. И было много раз: как он ни приходил, заходил туда вкусить хлеба. И сказала женщина мужу своему: «Вот, теперь я узнала, что это – святой человек Божий, тот кто проходит мимо нас постоянно; сделаем же ему горницу, небольшое место, и поставим ему там постель, и стол, и седалище, и светильник; и будет он, когда приходит к нам, туда и заходить. И был день, и пришел он туда, и зашел в горницу, и лег там. И сказал Гиезию, отроку своему: «Позови мне эту Соманитянку». И тот позвал её, и она стала пред ним. И сказал ему: «Скажи-ка ей: Вот, ты понесла ради нас всю эту заботу; что мы можем сделать для тебя? Нет ли у тебя дела к царю, или к начальникам войска?» Она же сказала: «(Нет), среди народа своего живу я [спокойно]». И сказал он Гиезию: «Что можем мы сделать для нее?» И сказал Гиезий, отрок его: «[И] правда, сына нет у неё, а муж её стар». И сказал он: «Позови её». И он позвал её, и стала она у двери. И сказал ей Елисей: «В эту пору, когда вновь придет это время, ты будешь жить [и] обнимать сына». Она же сказала: «Нет, господин мой, [человек Божий], не обманывай рабы твоей». И понесла во чреве женщина, и родила сына в ту пору, когда пришло время, и была жива, как сказал ей Елисей."},
  {"id": "ru-str-0602", "section": "service", "who": "reader", "text": "И подрос ребенок. И случилось, когда пошел ребенок к отцу своему, к жнецам, то сказал отцу своему: «Голова моя! голова моя болит!» И сказал тот отроку: «Отнеси его к матери его». И отнес его к матери его. И он лежал на коленях у неё до полудня, и умер. И отнесла она его, и положила его на постель человека Божия, и заперла его, и вышла. И позвала мужа своего и сказала: «Пришли-ка мне одного из отроков и одну из ослиц, и я съезжу к человеку Божию и возвращусь». Он сказал: «Что это ты идешь к нему? Сегодня не новомесячие и не суббота». Но она сказала: «Хорошо». И оседлала ослицу и сказала отроку своему: веди и иди; не задерживай меня на пути, пока не скажу тебе. Отправляйся, и пойдешь, и придешь к человеку Божию, к горе Кармил. И пошла, и пришла к человеку Божию, на гору Кармил."},
  {"id": "ru-str-0603", "section": "service", "who": "reader", "text": "И было, когда увидел Елисей, что она идет, то сказал Гиезию, отроку своему: «Смотри, эта Соманитянка. Беги навстречу к ней и скажи ей: «Благополучна (ли) ты? Благополучен (ли) муж твой? Благополучен (ли) ребенок?» Она же сказала: «Благополучны!» И пришла к Елисею на гору, и ухватилась за ноги его. И подошел Гиезий, чтобы отстранить её. И сказал Елисей: «Оставь её, ибо душа её страдает в ней; а Господь скрыл от меня и не возвестил мне». И сказала она: «Разве просила я сына у господина моего? Не сказала ли я: не обольщай меня»?» И сказал Елисей Гиезию: «Опояшь чресла твои и возьми посох мой в руку твою, и пойди; если встретишь человека, не приветствуй его, и если будет человек приветствовать тебя, не отвечай ему; и положишь посох мой на лицо ребенка». И сказала мать ребенка: «Жив Господь и жива душа твоя! Не отстану от тебя». И встал Елисей, и пошел за нею. А Гиезий прошел впереди нее и положил посох на лицо ребенка. Но не было голоса, и не было слышно ничего. И возвратился он навстречу ему, и возвестил ему, говоря: «Не пробудился ребенок»."},
  {"id": "ru-str-0604", "section": "service", "who": "reader", "text": "И вошел Елисей в дом; и вот, ребенок умерший лежит на постели его. И вошел Елисей в дом, и запер дверь за ними двумя. И помолился Господу, и поднялся и лег на ребенка, и приложил уста свои к устам его, и глаза свои к глазам его, и руки свои к рукам его, (и ноги свои к ногам его,) [и подышал на него,] и склонился над ним; и согрелось тело ребенка. И распрямился, и прошел по дому туда и сюда; и вновь возлег – и так простирался на ребенке до семи раз; и открыл ребенок глаза свои. И кликнул Елисей Гиезия и сказал: «Позови мне эту Соманитянку». И тот позвал её, и она вошла к нему. И сказал Елисей: «Возьми сына твоего». И подошла женщина, и упала к ногам его, и поклонилась до земли; и взяла сына своего и пошла. 4 Цар 4:8–37"},
  {"id": "ru-str-0605", "section": "service", "who": "reader", "text": "13. Пророчества Исаии чтение"},
  {"id": "ru-str-0606", "section": "service", "who": "reader", "text": "Так говорит Господь: Где Возведший из земли Пастыря овец (Своих)? Где вложивший в них Духа Святого? Проведший за правую руку Моисея мышцею славы Своей? Он заставил уйти воду от лица Своего, чтобы сделать Себе имя вечное, провел их через бездну, как коня по степи, и они не утомились, и как стадо по равнине. (И) сошел Дух от Господа и направил их – так вел Ты народ Твой, чтобы сделать Себе имя славное. Обратись, (Господи), с неба и воззри из жилища святыни Твоей и славы Твоей: где ревность Твоя и мощь Твоя? Где множество милости Твоей и сострадания Твоего – из-за чего Ты и терпел нас. Ведь Ты – Отец наш; ибо Авраам не узнал бы нас, и Израиль не признал бы нас. Но Ты, Господи – Отец наш; избавь нас: от века имя Твоё на нас. Для чего Ты, Господи, попустил нам сбиться с пути Твоего (и) ожесточиться сердцам нашим, чтобы не бояться Тебя? Обратись ради рабов Твоих, ради колен наследия Твоего, чтобы понемногу унаследовать нам гору святую Твою: противники наши попрали святыню Твою. Мы сделались, какими были от начала, когда Ты не властвовал нами и не именовалось имя Твоё над нами. Если Ты отверзешь небеса, трепет пред Тобою охватит горы, и они растают, как тает воск пред лицом огня. И попалит огонь противников, и явлено будет имя Твое среди врагов: от лица Твоего народы придут в смятение. Когда Ты совершишь дела славные, трепет пред Тобою охватит горы. От века мы не слышали, и глаза наши не видели бога, кроме Тебя, и дел Твоих, которые Ты совершишь для ожидающих милости: ибо встретит она ожидающих и творящих правду; и пути Твои вспомнятся им. Ис 63:11–19; 64:1–5"},
  {"id": "ru-str-0607", "section": "service", "who": "reader", "text": "14. Пророчества Иеремии чтение"},
  {"id": "ru-str-0608", "section": "service", "who": "reader", "text": "Так говорит Господь: Вот приходят дни, и заключу с домом Израиля и с домом Иуды завет новый, не как тот завет, который Я заключил с отцами их в тот день, когда Я взял их за руку, чтобы вывести их из земли Египетской; потому что они не пребыли в завете Моем, и Я пренебрег ими, говорит Господь. Ибо вот этот завет [Мой], который Я заключу с домом Израилевым после тех дней, говорит Господь: Непременно вложу законы Мои в разум их и на сердцах их напишу их, и буду им Богом, а они будут Моим народом. И не будет учить каждый ближнего своего, и каждый брата своего, говоря: «Познай Господа», ибо все будут знать Меня, от малого (и) до большого среди них, потому что Я милостив буду к неправдам их и грехов их не вспомню более. Иер 31:31–34"},
  {"id": "ru-str-0609", "section": "service", "who": "reader", "text": "15. Пророчества Даниила чтение"},
  {"id": "ru-str-0610", "section": "service", "who": "reader", "text": "В год восемнадцатый Навуходоносор царь сделал золотое изваяние: высота его шестьдесят локтей, ширина его шесть локтей, и поставил его на равнине Деира, в стране Вавилонской. И послал (Навуходоносор царь) собрать князей, и воевод, и наместников, вождей и правителей, и тех, кто стоит у власти, и всех начальников областей, чтобы они пришли на открытие изваяния, которое поставил Навуходоносор царь. И собрались наместники, князья, воеводы, вожди, верховные правители, стоящие у власти, и все начальники областей на открытие изваяния, которое поставил Навуходоносор царь, и стали перед изваянием, (которое поставил Навуходоносор царь). И глашатай воззвал с силою: «Вам объявляется, племена, народы, колена и языки: в то время, как услышите звук трубы, и свирели с цитрой, и лиры с гуслями, (и) симфонии и всякого рода музыки, падите и поклоняйтесь золотому изваянию, которое поставил Навуходоносор царь. А кто не падёт и не поклонится, тотчас будет брошен в печь, горящую огнем». И было, когда услышали народы звук трубы, и свирели с цитрой, и лиры с гуслями, и симфонии, и всякого рода музыки, то пали все народы, колена и языки, и поклонялись золотому изваянию, которое поставил Навуходоносор царь."},
  {"id": "ru-str-0611", "section": "service", "who": "reader", "text": "Тогда подошли некие мужи Халдейские и обвинили Иудеев. [И,] начав речь, сказали царю Навуходоносору: «Царь, вовеки живи! Ты, царь, дал повеление, чтобы всякий человек, который услышит звук трубы, и свирели с цитрой, и лиры с гуслями, и симфонии, и всякого рода музыки, и не падет, поклоняясь золотому изваянию, будет брошен в печь, горящую огнем. Так вот, есть мужи Иудейские, которых ты поставил над делами страны Вавилонской: Седрах, Мисах и Авденаго, которые не подчинились повелению твоему, царь; и богам твоим не служат, и золотому изваянию, которое ты поставил, не поклоняются»."},
  {"id": "ru-str-0612", "section": "service", "who": "reader", "text": "Тогда Навуходоносор во гневе и ярости приказал привести Седраха, Мисаха и Авденаго; и приведены они были пред лицо царя. И начал речь Навуходоносор, и сказал им: «Действительно ли вы, Седрах, Мисах и Авденаго, богам моим не служите, и золотому изваянию, которое я поставил, не поклоняетесь? Итак, ныне будьте готовы к тому, чтобы, когда услышите звук трубы, и свирели с цитрой, и лиры с гуслями, и симфонии, и всякого рода музыки, пасть и поклониться золотому изваянию, которое я поставил; если же не поклонитесь, тотчас брошены будете в печь, горящую огнем; и кто – тот Бог, который избавит вас из рук моих?»"},
  {"id": "ru-str-0613", "section": "service", "who": "reader", "text": "(И) ответили Седрах, Мисах и Авденаго, говоря царю Навуходоносору: «Нет нужды нам отвечать тебе на слово твое. Ибо есть на небесах Бог наш, Которому мы служим. Он силен спасти нас из печи, горящей огнем, и от рук твоих, царь, избавит нас. А если и не будет того, то да будет известно тебе, царь, что мы богам твоим не служим и золотому изваянию, которое ты поставил, не поклоняемся»."},
  {"id": "ru-str-0614", "section": "service", "who": "reader", "text": "Тогда Навуходоносор исполнился ярости, и вид лица его изменился на Седраха, Мисаха и Авденаго; и приказал он разжечь печь в семь раз сильнее, пока она до крайности не раскалится; и мужам крепким силою приказал, связав Седраха, Мисаха и Авденаго, бросить их в печь, горящую огнем. Тогда мужи те связаны были в шароварах своих, и шапочках, и сапогах – (в) одеждах их, и брошены в середину печи, горящей огнем. Поскольку слово царя превозмогло, и печь была раскалена чрезвычайно, [в семь раз сильнее], (то мужей тех, которые бросали Седраха, Мисаха и Авденаго, убило пламя огня). А эти три (мужа), Седрах, Мисах и Авденаго, упали в середину печи, огнем горящей, связанные. И ходили посреди пламени, воспевая и славя Бога и благословляя Господа."},
  {"id": "ru-str-0615", "section": "service", "who": "reader", "text": "И, став (с ними), Азария стал молиться и, открыв уста свои среди огня, возгласил так:"},
  {"id": "ru-str-0616", "section": "service", "who": "reader", "text": "«Благословен Ты, Господи, Боже отцов наших, и хвально и прославлено имя Твоё вовеки,"},
  {"id": "ru-str-0617", "section": "service", "who": "reader", "text": "Ибо праведен Ты во всём, что соделал с нами, и все дела Твои истинны, и правы пути Твои, и все суды Твои истинны;"},
  {"id": "ru-str-0618", "section": "service", "who": "reader", "text": "И суды истинные Ты сотворил во всем, что навёл на нас и на святой град отцов наших Иерусалим, потому что по истине и по суду навёл Ты всё это на нас за грехи наши."},
  {"id": "ru-str-0619", "section": "service", "who": "reader", "text": "Ибо согрешили мы, и поступили беззаконно, отступив от Тебя, и согрешили во всём, и заповедей Твоих не послушали, и не соблюли, и не соделали, как Ты повелел нам, чтобы благо нам было."},
  {"id": "ru-str-0620", "section": "service", "who": "reader", "text": "И всё, что Ты навёл на нас, и всё, что Ты соделал с нами, соделал по истинному суду, и предал нас в руки врагов беззаконных, враждебнейших отступников, и царю неправедному и злейшему на всей земле."},
  {"id": "ru-str-0621", "section": "service", "who": "reader", "text": "И ныне не открыть нам уст; мы сделались стыдом и поношением для рабов Твоих и чтущих Тебя."},
  {"id": "ru-str-0622", "section": "service", "who": "reader", "text": "Не предай же нас до конца ради имени Твоего [святого], и не разрушь завета Твоего, и не удали милости Твоей от нас ради Авраама, возлюбленного Тобою, и ради Исаака, раба Твоего, и Израиля, святого Твоего, которым Ты сказал, говоря им, что умножишь семя их, как звёзды небесные и как песок на берегу моря."},
  {"id": "ru-str-0623", "section": "service", "who": "reader", "text": "Ибо мы умалились, Владыка, более всех народов, и унижены сегодня на всей земле за грехи наши,"},
  {"id": "ru-str-0624", "section": "service", "who": "reader", "text": "И нет у нас в настоящее время ни князя, ни пророка, ни вождя, ни всесожжения, ни жертвы, ни приношения, ни фимиама, ни места, чтобы нам принести плоды пред лицо Твоё и обрести милость."},
  {"id": "ru-str-0625", "section": "service", "who": "reader", "text": "Но с душою сокрушённой и духом смирения да будем приняты, как при всесожжениях овнов и тельцов и как при десятках тысяч агнцев тучных, так да сделается жертва наша пред Тобою сегодня, и да совершится для Тебя, – ибо нет стыда уповающим на Тебя."},
  {"id": "ru-str-0626", "section": "service", "who": "reader", "text": "И ныне мы следуем [за Тобою] всем сердцем, и боимся Тебя, и ищем лица Твоего;"},
  {"id": "ru-str-0627", "section": "service", "who": "reader", "text": "Не постыди нас, но сотвори с нами по снисхождению Твоему и по множеству милости Твоей,"},
  {"id": "ru-str-0628", "section": "service", "who": "reader", "text": "(И) избавь нас силою чудес Твоих, и дай славу имени Твоему, Господи,"},
  {"id": "ru-str-0629", "section": "service", "who": "reader", "text": "И да посрамятся все делающие рабам Твоим зло, и да постыдятся со всею силою [и могуществом], и мощь их да сокрушится,"},
  {"id": "ru-str-0630", "section": "service", "who": "reader", "text": "И да познают, что Ты, Господи, Бог единый и славный по всей вселенной»."},
  {"id": "ru-str-0631", "section": "service", "who": "reader", "text": "И не переставали слуги царя, бросившие их, разжигать печь нефтью, смолою, паклею и хворостом, и растекалось пламя над печью на сорок девять локтей; и выходило, и сжигало тех из Халдеев, которых достигало около печи. Но Ангел Господень сошел вместе с бывшими с Азарией в печь, и выбросил пламя огня из печи, и сделал, что в средине печи был как бы шумящий влажный ветер, и совсем не коснулся их огонь, и не повредил им, и не обеспокоил их. Тогда эти трое, как бы едиными устами, воспевали, и благословляли, и славили Бога в печи, возглашая:"},
  {"id": "ru-str-0632", "section": "service", "who": "reader", "text": "«Благословен Ты, Господи Боже отцов наших, (и) прехвальный и превозносимый вовеки, и благословенно имя славы Твоей, святое (и) прехвальное и превозносимое вовеки."},
  {"id": "ru-str-0633", "section": "service", "who": "reader", "text": "Благословен Ты в храме святой славы Твоей, (и) прехвальный и преславный вовеки."},
  {"id": "ru-str-0634", "section": "service", "who": "reader", "text": "Благословен Ты, видящий бездны, восседающий на Херувимах, (и) прехвальный и превозносимый вовеки."},
  {"id": "ru-str-0635", "section": "service", "who": "reader", "text": "Благословен Ты на престоле славы царства Твоего, (и) прехвальный и превозносимый вовеки."},
  {"id": "ru-str-0636", "section": "service", "who": "reader", "text": "Благословен Ты на тверди небесной, (и) прехвальный и превозносимый вовеки»."},
  {"id": "ru-str-0637", "section": "service", "who": "reader", "text": "Песнь трёх отроков"},
  {"id": "ru-str-0638", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0639", "section": "service", "who": "reader", "text": "Благословляйте, все дела Господни."},
  {"id": "ru-str-0640", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0641", "section": "service", "who": "choir", "text": "Благословляйте, Ангелы Господни."},
  {"id": "ru-str-0642", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0643", "section": "service", "who": "choir", "text": "Благословляйте, небеса Господни."},
  {"id": "ru-str-0644", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0645", "section": "service", "who": "choir", "text": "Благословляйте, все воды, что превыше небес."},
  {"id": "ru-str-0646", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0647", "section": "service", "who": "choir", "text": "Благословляйте, все силы Господни."},
  {"id": "ru-str-0648", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0649", "section": "service", "who": "choir", "text": "Благословляйте, солнце и луна."},
  {"id": "ru-str-0650", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0651", "section": "service", "who": "choir", "text": "Благословляйте, звёзды небесные."},
  {"id": "ru-str-0652", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0653", "section": "service", "who": "choir", "text": "Благословляйте, всякий дождь и роса."},
  {"id": "ru-str-0654", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0655", "section": "service", "who": "choir", "text": "Благословляйте, все ветры."},
  {"id": "ru-str-0656", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0657", "section": "service", "who": "choir", "text": "Благословляйте, огонь и жар."},
  {"id": "ru-str-0658", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0659", "section": "service", "who": "choir", "text": "Благословляйте, холод и зной."},
  {"id": "ru-str-0660", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0661", "section": "service", "who": "choir", "text": "Благословляйте, росы и вьюги."},
  {"id": "ru-str-0662", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0663", "section": "service", "who": "choir", "text": "Благословляйте, лед и мороз."},
  {"id": "ru-str-0664", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0665", "section": "service", "who": "choir", "text": "Благословляйте, инеи и снега."},
  {"id": "ru-str-0666", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0667", "section": "service", "who": "choir", "text": "Благословляйте, ночи и дни."},
  {"id": "ru-str-0668", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0669", "section": "service", "who": "choir", "text": "Благословляйте, свет и тьма."},
  {"id": "ru-str-0670", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0671", "section": "service", "who": "choir", "text": "Благословляйте, молнии и облака."},
  {"id": "ru-str-0672", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0673", "section": "service", "who": "choir", "text": "Да благословляет земля."},
  {"id": "ru-str-0674", "section": "service", "who": "choir", "text": "Господа, да поёт и превозносит Его вовеки."},
  {"id": "ru-str-0675", "section": "service", "who": "choir", "text": "Благословляйте, горы и холмы."},
  {"id": "ru-str-0676", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0677", "section": "service", "who": "choir", "text": "Благословляйте, всё произрастающее на земле."},
  {"id": "ru-str-0678", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0679", "section": "service", "who": "choir", "text": "Благословляйте, источники."},
  {"id": "ru-str-0680", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0681", "section": "service", "who": "choir", "text": "Благословляйте, моря и реки."},
  {"id": "ru-str-0682", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0683", "section": "service", "who": "choir", "text": "Благословляйте, киты и всё, движущееся в водах."},
  {"id": "ru-str-0684", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0685", "section": "service", "who": "choir", "text": "Благословляйте, все птицы небесные."},
  {"id": "ru-str-0686", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0687", "section": "service", "who": "choir", "text": "Благословляйте, звери и весь скот."},
  {"id": "ru-str-0688", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0689", "section": "service", "who": "choir", "text": "Благословляйте, сыны человеческие."},
  {"id": "ru-str-0690", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0691", "section": "service", "who": "choir", "text": "Да благословляет Израиль."},
  {"id": "ru-str-0692", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0693", "section": "service", "who": "choir", "text": "Благословляйте, священники Господни."},
  {"id": "ru-str-0694", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0695", "section": "service", "who": "choir", "text": "Благословляйте, рабы Господни."},
  {"id": "ru-str-0696", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0697", "section": "service", "who": "choir", "text": "Благословляйте, духи и души праведных."},
  {"id": "ru-str-0698", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0699", "section": "service", "who": "choir", "text": "Благословляйте, благоговейные и смиренные сердцем."},
  {"id": "ru-str-0700", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0701", "section": "service", "who": "choir", "text": "Благословляйте, Анания, Азария и Мисаил."},
  {"id": "ru-str-0702", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0703", "section": "service", "who": "choir", "text": "Благословляйте, Апостолы, пророки и мученики Господни."},
  {"id": "ru-str-0704", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0705", "section": "service", "who": "choir", "text": "Благословим Отца, и Сына, и Святого Духа!"},
  {"id": "ru-str-0706", "section": "service", "who": "choir", "text": "Господа, поём и превозносим Его вовеки."},
  {"id": "ru-str-0707", "section": "service", "who": "choir", "text": "И ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-str-0708", "section": "service", "who": "choir", "text": "Господа, пойте и превозносите Его вовеки."},
  {"id": "ru-str-0709", "section": "service", "who": "reader", "text": "Хвалим, благословляем, поклоняемся Господу."},
  {"id": "ru-str-0710", "section": "service", "who": "choir", "text": "Воспевая и превознося Его вовеки. Дан 3:1–88"},
  {"id": "ru-str-0711", "section": "service", "who": "rubric", "text": "И начинается Литургия св. Василия Великого: Ектения малая, молитва Трисвятого."},
  {"id": "ru-str-0712", "section": "service", "who": "choir", "text": "Вместо Трисвятого поем:"},
  {"id": "ru-str-0713", "section": "service", "who": "choir", "text": "Сколько вас во Христа ни крестилось, / во Христа вы все облеклись. Аллилуия. (3)"},
  {"id": "ru-str-0714", "section": "service", "who": "choir", "text": "Прокимен, глас 8"},
  {"id": "ru-str-0715", "section": "service", "who": "choir", "text": "Вся земля да поклонится Тебе и да поёт Тебе, / да поёт же имени Твоему, Всевышний. Стих:"},
  {"id": "ru-str-0716", "section": "service", "who": "choir", "text": "Воскликните Господу, вся земля, воспойте же имени Его. Пс 65:4, 1–2а"},
  {"id": "ru-str-0717", "section": "service", "who": "choir", "text": "Апостол Послание к Римлянам, зачало 91"},
  {"id": "ru-str-0718", "section": "service", "who": "choir", "text": "Братья, все мы, кто были крещены во Христа Иисуса, в смерть Его были крещены. Итак мы были с Ним погребены чрез крещение в смерть, чтобы, как был воздвигнут Христос из мёртвых славою Отца, так и мы ходили бы в обновлении жизни. Ибо если мы оказались сращенными с Ним подобием смерти Его, мы, конечно, будем сращены и подобием воскресения, зная то, что ветхий наш человек был распят с Ним, дабы упразднено было тело греха, так чтобы не быть нам больше рабами греха; ибо умерший свободен от греха. Если же мы умерли со Христом, то верим, что и жить будем с Ним, зная, что Христос, восстав из мёртвых, больше не умирает, смерть больше не имеет над Ним власти. Ибо, что Он умер, то умер раз навсегда греху, а что живет, то живет Богу. Так и вы считайте, что вы мертвы греху, но живы Богу во Христе Иисусе, Господе нашем. Рим 6:3–11"},
  {"id": "ru-str-0719", "section": "service", "who": "rubric", "text": "Вместо Аллилуия поем псалом 81 повторяя после каждого стиха на 7 глас:"},
  {"id": "ru-str-0720", "section": "service", "who": "choir", "text": "Восстань, Боже, суди землю, ибо Ты получишь удел во всех народах! Стих:"},
  {"id": "ru-str-0721", "section": "service", "who": "choir", "text": "Бог стал в сонме богов, среди богов совершает суд. Стих:"},
  {"id": "ru-str-0722", "section": "service", "who": "choir", "text": "Доколе вы судите неправедно и лицеприятствуете к грешным? Стих:"},
  {"id": "ru-str-0723", "section": "service", "who": "choir", "text": "Судите сироту и бедного, смиренного и нищего оправдайте. Стих:"},
  {"id": "ru-str-0724", "section": "service", "who": "choir", "text": "Освободите нищего и бедного, из руки грешника избавьте его. Стих:"},
  {"id": "ru-str-0725", "section": "service", "who": "choir", "text": "Не познали они и не поняли, во тьме блуждают, – потрясутся все основания земли! Стих:"},
  {"id": "ru-str-0726", "section": "service", "who": "choir", "text": "Я сказал: вы – боги, и все вы – сыны Всевышнего, но вы как люди умираете, и как один из князей падаете."},
  {"id": "ru-str-0727", "section": "service", "who": "choir", "text": "Восстань, Боже, суди землю, ибо Ты получишь удел во всех народах!"},
  {"id": "ru-str-0728", "section": "service", "who": "rubric", "text": "Священнослужители в это время переоблачаются в белые облачения."},
  {"id": "ru-str-0729", "section": "service", "who": "choir", "text": "Евангелие от Матфея, зачало 115"},
  {"id": "ru-str-0730", "section": "service", "who": "choir", "text": "По прошествии субботы, на рассвете первого дня недели, пришла Мария Магдалина и другая Мария посмотреть гробницу. И вот, произошло великое землетрясение, ибо Ангел Господень, сойдя с неба и подойдя, отвалил камень и сидел на нем. Был же вид его как молния, и одежда его бела как снег. Страхом перед ним были потрясены стерегущие и стали как мертвые. И заговорил Ангел и сказал женщинам: не бойтесь; я знаю, что вы Иисуса распятого ищете. Его нет здесь: ибо восстал Он, как сказал. Подойдите, посмотрите место, где Он лежал, и идите скорее, скажите ученикам Его, что Он восстал из мертвых, и вот, Он предваряет вас в Галилее; там вы Его увидите. Вот, я сказал вам. И уйдя скоро от гробницы, со страхом и радостью великой побежали они возвестить ученикам Его. И вот, Иисус встретил их и сказал: радуйтесь. Они же, подойдя, ухватились за ноги Его и поклонились Ему. Тогда говорит им Иисус: не бойтесь; идите, возвестите братьям Моим, чтобы шли в Галилею, и там они Меня увидят. Когда же они шли, некоторые из стражи пришли в город и возвестили первосвященникам о всем происшедшем. И они, собравшись со старейшинами и приняв решение, дали воинам достаточно денег, говоря: скажите: «ученики Его, придя ночью, украли Его, пока мы спали». И если это станет известно у правителя, мы уладим дело и избавим вас от неприятностей. Они же, взяв деньги, поступили, как были научены. И слово это было разглашено среди Иудеев до сего дня. Одиннадцать же учеников отправились в Галилею на гору, куда повелел им Иисус. И, увидев Его, поклонились; другие же усомнились. И подойдя, Иисус сказал им: дана Мне всякая власть на небе и на земле. Итак, идите, научите все народы, крестя людей во имя Отца и Сына и Святого Духа, уча их соблюдать все, что Я заповедал вам. И вот, Я с вами все дни до конца века. Аминь. Мф 28:1–20"},
  {"id": "ru-str-0731", "section": "service", "who": "choir", "text": "Вместо Херувимской песни, тропарь, глас 8"},
  {"id": "ru-str-0732", "section": "service", "who": "choir", "text": "Да умолкнет всякая плоть человеческая, / и да стоит со страхом и трепетом, / и ни о чем земном в себе да не помышляет, / ибо Царь царствующих и Господь господствующих / приходит заклаться и дать Себя в пищу верным. / Пред Ним шествуют сонмы Ангелов / со всяким их начальством и властью, / многоокие Херувимы и шестикрылые Серафимы, / закрывая лица и возглашая песнь: / аллилуия, аллилуия, аллилуия."},
  {"id": "ru-str-0733", "section": "service", "who": "choir", "text": "Вместо «Достойно»"},
  {"id": "ru-str-0734", "section": "service", "who": "rubric", "text": "Ирмос, глас 6:"},
  {"id": "ru-str-0735", "section": "service", "who": "choir", "text": "Не рыдай надо Мною, Матерь, / видя во гробе Сына, / Которого Ты во чреве без семени зачала, / ибо Я воскресну и буду прославлен, / и во славе вознесу, как Бог, / непрестанно с верою и любовию / Тебя величающих."},
  {"id": "ru-str-0736", "section": "service", "who": "choir", "text": "Причастен, глас 4"},
  {"id": "ru-str-0737", "section": "service", "who": "choir", "text": "Как спящий, пробудился Господь, и воскрес спасая нас. Аллилуия. (3)"},
  {"id": "ru-str-0738", "section": "service", "who": "choir", "text": "Ср. Пс 77:65А"},
  {"id": "ru-str-0739", "section": "service", "who": "rubric", "text": "После заамвонной молитвы поем тропари Великой субботы; в это время совершается каждение хлебов и вина."},
  {"id": "ru-str-0740", "section": "service", "who": "rubric", "text": "Затем диакон говорит:"},
  {"id": "ru-str-0741", "section": "service", "who": "deacon", "text": "Господу помолимся!"},
  {"id": "ru-str-0742", "section": "service", "who": "rubric", "text": "Священник же читает молитву:"},
  {"id": "ru-str-0743", "section": "service", "who": "priest", "text": "Господи Иисусе Христе, Боже наш, благословивший пять хлебов и пять тысяч насытивший! Сам благослови и эти хлебы и вино, и умножь их во граде нашем, (или:"},
  {"id": "ru-str-0744", "section": "service", "who": "priest", "text": "в селе нашем , или:"},
  {"id": "ru-str-0745", "section": "service", "who": "priest", "text": "в святой обители сей )"},
  {"id": "ru-str-0746", "section": "service", "who": "priest", "text": "и во всём мире Твоём, и верных, вкушающих их, освяти. Ибо Ты благословляешь и освящаешь всё, Христе Боже наш, и Тебе славу воссылаем, со безначальным Твоим Отцом и всесвятым и благим и животворящим Твоим Духом ныне, и всегда, и во веки веков."},
  {"id": "ru-str-0747", "section": "service", "who": "choir", "text": "Аминь."},
  {"id": "ru-str-0748", "section": "service", "who": "rubric", "text": "И обычное окончание Литургии."},
  {"id": "ru-str-0749", "section": "service", "who": "rubric", "text": "Отпуст:"},
  {"id": "ru-str-0750", "section": "service", "who": "choir", "text": "Христос, истинный Бог наш:"},
  {"id": "ru-str-0751", "section": "service", "who": "rubric", "text": "[В старопечатных служебниках для Литургии Великой Субботы имелся особый отпуст:"},
  {"id": "ru-str-0752", "section": "service", "who": "choir", "text": "Нас ради и нашего ради спасения смиривший Себя и в нашу нищету облекшийся, и добровольно страдания претерпевший, и смерть вкусивший, и во гробе положенный Христос, истинный Бог наш, по молитвам Пречистой Своей Матери, святых славных и всехвальных Апостолов, святого отца нашего Василия Великого, архиепископа Кесарии Каппадокийской и всех святых, помилует и спасёт нас, как благой и Человеколюбец. ]"},
  {"id": "ru-str-0753", "section": "service", "who": "rubric", "text": "Долженствует же екклисиарх имети опасство, да егда скончавается литургиа, будет час вторый нощи. По отпусте же не исходим из церкве, но седим на местех наших: и входит келарь, и дает братии по единому укруху хлеба и по шести смоквей или фиников, и по единому красовулю вина. Нам же возлежащим, бывает чтение великое в Деяниих святых Апостол от начала. Глаголет же чтец начало. Священник же стих: Молитвами святых апостол, Господи Иисусе Христе Боже наш, помилуй нас. И по Амине начинает чтец чести. Таже начинаем ясти. И по скончании чтения вжигает кандиловжигатель вся кандила храма, и, исходя, ударяет в клепало: и престает чтый чтение."},
  {"id": "ru-str-0754", "section": "service", "who": "choir", "text": "ПОЛУНОЩНИЦА ВО СВЯТУЮ И ВЕЛИКУЮ СУББОТУ"},
  {"id": "ru-str-0755", "section": "service", "who": "rubric", "text": "Обычное начало полунощницы: Трисвятое, и далее как обычно:"},
  {"id": "ru-str-0756", "section": "service", "who": "choir", "text": "Придите, поклонимся: (3), псалом 50. И канон Великой субботы: ирмосы дважды, тропари на 12, со стихами песней. Катавасия: оба хора – ирмос."},
  {"id": "ru-str-0757", "section": "service", "who": "choir", "text": "Канон, глас 6. Песнь 1 Ирмос:"},
  {"id": "ru-str-0758", "section": "service", "who": "choir", "text": "Волною морскою / Покрывшего в древности / преследователя-тирана / сокрыли под землею / дети Им спасенных; / но мы, как юные девы, / Господу воспоем: / ибо славно Он прославился."},
  {"id": "ru-str-0759", "section": "service", "who": "choir", "text": "Господи Боже мой! / Отходное песнопение / и надгробную песнь воспою Тебе, / погребением Своим входы жизни мне отворившему / и смертию смерть и ад умертвившему."},
  {"id": "ru-str-0760", "section": "service", "who": "choir", "text": "В высоте – на престоле / и внизу – во гробе / надмирные и подземные существа / созерцая Тебя, Спаситель мой, / сотрясались при умерщвлении Твоем: / ибо превыше разума Ты явился мертвым, / жизни Первоначальник."},
  {"id": "ru-str-0761", "section": "service", "who": "choir", "text": "Дабы Своею славою / все наполнить, / Ты нисшел в глубочайшие места земли; / ибо не скрылось от Тебя / естество мое, то, что у Адама, / и, погребенный, Ты обновляешь / меня, истлевшего, Человеколюбец."},
  {"id": "ru-str-0762", "section": "service", "who": "choir", "text": "Песнь 3 Ирмос:"},
  {"id": "ru-str-0763", "section": "service", "who": "choir", "text": "Тебя, на водах / повесившего всю землю без опоры, / творение увидев висящим на лобном месте, / великим ужасом охваченное, восклицало: / «Нет святого, кроме Тебя, Господи!»"},
  {"id": "ru-str-0764", "section": "service", "who": "choir", "text": "Образы погребения Твоего / Ты показал во множестве видений; / а ныне тайны Свои, Владыка, / Ты богочеловечески явил и находившимся во аде, восклицавшим: / «Нет святого, кроме Тебя, Господи!»"},
  {"id": "ru-str-0765", "section": "service", "who": "choir", "text": "Ты распростер длани / и соединил прежде разделенное; / а облечением, Спаситель, / в полотно и гроб / Ты освободил и скованных цепями, восклицавших: / «Нет святого, кроме Тебя, Господи!»"},
  {"id": "ru-str-0766", "section": "service", "who": "choir", "text": "В гробнице и за печатями / Ты, Невместимый, был удержан добровольно; / и, действительно, силу Свою / Ты божественно явил делами воспевающим: / «Нет святого, кроме Тебя, Господи, Человеколюбец!»"},
  {"id": "ru-str-0767", "section": "service", "who": "choir", "text": "Седален, глас 1 Воины, охранявшие гроб Твой, Спаситель, / стали как мертвые от блистания явившегося Ангела, / возвещавшего женам о воскресении. / Тебя мы славим, тления истребителя, / к Тебе припадаем, воскресшему из гроба, /и единому Богу нашему."},
  {"id": "ru-str-0768", "section": "service", "who": "choir", "text": "Слава, и ныне:"},
  {"id": "ru-str-0769", "section": "service", "who": "rubric", "text": "повторяем то же."},
  {"id": "ru-str-0770", "section": "service", "who": "choir", "text": "Песнь 4 Ирмос:"},
  {"id": "ru-str-0771", "section": "service", "who": "choir", "text": "На Кресте Твое божественное умаление провидя, / Аввакум в изумлении взывал: / «Ты пресек, Благой, могущество властителей, / приобщаясь к находящимся во аде, / как всесильный!»"},
  {"id": "ru-str-0772", "section": "service", "who": "choir", "text": "День седьмой Ты сегодня освятил, / который прежде благословил упокоением от дел; / ибо Ты изменяешь все, Спаситель мой, и обновляешь, / покоясь, – и к Себе привлекая."},
  {"id": "ru-str-0773", "section": "service", "who": "choir", "text": "Когда Ты силой высшей одержал победу, / душа Твоя от тела отделилась; / но то и другое расторгает / узы смерти и ада / могуществом Твоим, Слово."},
  {"id": "ru-str-0774", "section": "service", "who": "choir", "text": "Ад встретившись с Тобою, Слово, ожесточился, / видя смертного обоженным, / изъязвленным ранами и вместе – всесильным, / но погиб от страха пред этим образом."},
  {"id": "ru-str-0775", "section": "service", "who": "choir", "text": "Песнь 5 Ирмос:"},
  {"id": "ru-str-0776", "section": "service", "who": "choir", "text": "Богоявления Твоего к нам, Христе, / из сострадания происшедшего, / Исаия увидев свет немеркнущий, / от ночи бодрствуя восклицал: / «Воскреснут мертвые, / и восстанут находящиеся в гробницах, / и все, на земле живущие, возрадуются!»"},
  {"id": "ru-str-0777", "section": "service", "who": "choir", "text": "Ты обновляешь рожденных на земле, Создатель, / Сам явившись созданным из праха, / и полотно и гроб указывают, Слово, / на связанное с Тобою таинство; / ибо почтенный член совета представляет / замысел Твоего Родителя, / в Тебе величественно обновляющего меня."},
  {"id": "ru-str-0778", "section": "service", "who": "choir", "text": "Смертию Ты изменяешь смертное, / погребением – тленное; / ибо Ты неизменным пребываешь, как подобает Богу, / делая бессмертным то, что принял: / ведь ни плоть Твоя не увидела тления, Владыка, / ни душа Твоя во аде дивным образом не оставлена."},
  {"id": "ru-str-0779", "section": "service", "who": "choir", "text": "От Безбрачной происшедший и пронзенный в ребра, / Ты чрез Нее, Создатель мой, / Евы совершил восстановление, / новым Адамом став, / уснув сном животворным сверхъестественно, / и жизнь пробудив от сна и тления, / как Всесильный."},
  {"id": "ru-str-0780", "section": "service", "who": "choir", "text": "Песнь 6 Ирмос:"},
  {"id": "ru-str-0781", "section": "service", "who": "choir", "text": "Был объят, но не удержан недрами кита Иона; / ибо нося образ Тебя, пострадавшего и погребению преданного, / он вышел из зверя, как из чертога, / а к страже гроба Твоего взывал: / «Соблюдающие суетное и ложное, / Самую Милость вы оставили!»"},
  {"id": "ru-str-0782", "section": "service", "who": "choir", "text": "Ты умерщвлен был, но не разделился, Слово, / с плотью, к которой приобщился; / ибо хотя и разрушился Твой храм во время страдания, / но и тогда была едина Ипостась / Божества и плоти Твоей, / ведь в обоих естествах Ты пребываешь, один Сын, / Слово Божие, Бог и человек."},
  {"id": "ru-str-0783", "section": "service", "who": "choir", "text": "Смертоносно для людей, но не для Бога, / было падение Адама, / ибо хотя и пострадало естество плоти Твоей, созданной из праха, / но бесстрастным осталось Божество, / а тленное Ты в Себе претворил в нетленное / и явил источник нетленной жизни воскресением."},
  {"id": "ru-str-0784", "section": "service", "who": "choir", "text": "Царствует ад, но не вечно, / над родом человеческим; / ибо Ты, Могущественный, положенный во гробе, / живоначальной дланию расторг засовы смерти / и возвестил сидевшим там от века истинное избавление, / став, Спаситель, первенцем из мертвых."},
  {"id": "ru-str-0785", "section": "service", "who": "choir", "text": "Кондак, глас 6 Бездну Заключивший / лежит пред нами мертвым, / и, полотном со смирною обвитый, / в гробнице полагается как смертный – Бессмертный. / Жены же пришли помазать Его миром, / плача горько и взывая: / «Эта суббота – преблагословенна, / та самая, когда Христос уснул, / чтобы на третий день воскреснуть». Икос:"},
  {"id": "ru-str-0786", "section": "service", "who": "choir", "text": "Все Удерживающий на Кресте был возвышен, / и рыдает все творение, / видя Его обнаженным, висящим на Древе; / солнце скрыло лучи, и звезды лишились света; / земля же в великом страхе поколебалась, / море побежало и камни распались, / а многие гробницы открылись, / и восстали тела святых мужей. / Ад внизу стенает, а Иудеи замышляют оклеветать Христово воскресение, / но жены взывают: / «Эта суббота – преблагословенна, / та самая, когда Христос уснул, / чтобы на третий день воскреснуть»."},
  {"id": "ru-str-0787", "section": "service", "who": "choir", "text": "Песнь 7 Ирмос:"},
  {"id": "ru-str-0788", "section": "service", "who": "choir", "text": "Неизреченное чудо! / Избавивший благочестивых отроков в печи от пламени / во гробе мертвым, бездыханным погребается, / ко спасению нас, поющих: / «Боже, Искупитель, благословен Ты!»"},
  {"id": "ru-str-0789", "section": "service", "who": "choir", "text": "Уязвлен в сердце ад, / приняв Пронзенного копьем в ребра, / и стенает, огнем божественным поглощаемый, / ко спасению нас, поющих: / «Боже, Искупитель, благословен Ты!»"},
  {"id": "ru-str-0790", "section": "service", "who": "choir", "text": "Богат гроб! / Ведь приняв в себя / как бы уснувшего Создателя, / он явлен божественной сокровищницей жизни, / ко спасению нас, поющих: / «Боже, Искупитель, благословен Ты!»"},
  {"id": "ru-str-0791", "section": "service", "who": "choir", "text": "По закону смертных / положению во гробе / подвергается Жизнь всех / и источником воскресения его являет, / ко спасению нас, поющих: / «Боже, Искупитель, благословен Ты!»"},
  {"id": "ru-str-0792", "section": "service", "who": "choir", "text": "Единым было во аде, / и во гробе, и в Эдеме / Божество Христа, нераздельное с Отцом и Духом, / ко спасению нас поющих: / «Боже, Искупитель, благословен Ты!»"},
  {"id": "ru-str-0793", "section": "service", "who": "choir", "text": "Песнь 8 Ирмос:"},
  {"id": "ru-str-0794", "section": "service", "who": "choir", "text": "Изумись в трепете, небо, / и да потрясутся основания земли; / ибо вот, к мертвым причисляется / на высотах Живущий / и в тесном гробе помещается; / Его отроки благословляйте, / священники воспевайте, / люди превозносите во все века."},
  {"id": "ru-str-0795", "section": "service", "who": "choir", "text": "Разрушен пречистый храм, / но с Собой Он восстанавливает падшую скинию, / ибо к первому Адам второй, / на высотах Живущий, / сошел даже до внутренних хранилищ ада: / Его отроки благословляйте, священники воспевайте, / люди превозносите во все века."},
  {"id": "ru-str-0796", "section": "service", "who": "choir", "text": "Не стало дерзновения у учеников, / но отличается Аримафеянин Иосиф, / ибо мертвым и обнаженным Всевышнего Бога видя, / он испрашивает Его и погребает, восклицая: / «Отроки благословляйте, священники воспевайте, / люди превозносите во все века!»"},
  {"id": "ru-str-0797", "section": "service", "who": "choir", "text": "О необычайные чудеса! О благость! / О неизреченное терпение! / Под землею добровольно запечатывается / на высотах Живущий, / и Бог, как обманщик, ложно обвиняется: / Его отроки благословляйте, священники воспевайте, / люди превозносите во все века."},
  {"id": "ru-str-0798", "section": "service", "who": "choir", "text": "Песнь 9 Ирмос:"},
  {"id": "ru-str-0799", "section": "service", "who": "choir", "text": "Не рыдай надо Мною, Матерь, / видя во гробе Сына, / Которого Ты во чреве без семени зачала, / ибо Я воскресну и буду прославлен, / и во славе вознесу, как Бог, / непрестанно с верою и любовию / Тебя величающих."},
  {"id": "ru-str-0800", "section": "service", "who": "choir", "text": "При дивном Твоем рождестве / сверхъестественно избежав мучений, / Я была прославлена, Сын безначальный; / ныне же, видя Тебя, Боже Мой, бездыханным, мертвым, / Я мечом скорби терзаюсь страшно; / но воскресни, чтобы Мне возвеличиться."},
  {"id": "ru-str-0801", "section": "service", "who": "choir", "text": "Земля покрывает Меня по Моей воле, / но трепещут привратники ада, / видя Меня, Матерь, / облеченного в окровавленную одежду мщения, / ибо поразив врагов на Кресте, как Бог, / Я опять воскресну и возвеличу Тебя."},
  {"id": "ru-str-0802", "section": "service", "who": "choir", "text": "Да радуется творение, / да веселятся все, на земле рожденные, / ибо у ада ненавистного отнята добыча; / пусть жены с ароматами Меня встречают; / Я избавляю Адама и Еву со всем их родом, / и в третий день воскресну."},
  {"id": "ru-str-0803", "section": "service", "who": "rubric", "text": "После девятой песни Трисвятое."},
  {"id": "ru-str-0804", "section": "service", "who": "choir", "text": "Тропарь, глас 2: Когда сошел Ты к смерти, Жизнь бессмертная, / тогда ад умертвил Ты сиянием Божества. / Когда же Ты и умерших из преисподней воскресил, / все Силы Небесные взывали: / «Податель жизни, Христе Боже наш, слава Тебе!»"},
  {"id": "ru-str-0805", "section": "service", "who": "rubric", "text": "Ектения сугубая и отпуст:"},
  {"id": "ru-str-0806", "section": "service", "who": "choir", "text": "Христос, истинный Бог наш:"},
];

